/* 학습 해설
 * Flow limit: 최근 해시 버킷 기록으로 한 흐름의 독점 줄이기
 * 큐가 붐빌 때 특정 흐름이 최근 패킷의 대부분을 차지하면 다른 흐름의 패킷도 함께 밀릴 수 있습니다. 최근 흐름 분포를 작은 이력 배열로 근사해 한 버킷이 과도하게 차지하는 경우를 제한합니다.
 * CONFIG_NET_FLOW_LIMIT에서 qlen이 max_backlog의 절반보다 작으면 즉시 false입니다. 그 외 현재 CPU의 flow_limit을 RCU로 읽습니다. 있으면 hash&(num_buckets-1)로 새 버킷을 정하고 순환 이력의 옛 버킷을 새 값으로 교체합니다. history_head를 증가시킨 뒤 마스크로 순환시키며 옛 버킷 계수가 양수일 때1을 빼고 새 버킷에1을 더합니다.
 * 설명용 이력 길이H=8이면 새 버킷 계수가4일 때는 통과하고5가 되면 H/2 초과라 true입니다. true일 때 fl->count도 증가합니다. 옛 버킷과 새 버킷이 같고 계수가 양수이면 빼고 더해 같은 값이 됩니다. 실제 이력 길이는 FLOW_LIMIT_HISTORY 상수이며 H=8은 계산용 예입니다.
 */
static bool skb_flow_limit(struct sk_buff *skb, unsigned int qlen)
{
#ifdef CONFIG_NET_FLOW_LIMIT
	struct sd_flow_limit *fl;
	struct softnet_data *sd;
	unsigned int old_flow, new_flow;

	if (qlen < (READ_ONCE(net_hotdata.max_backlog) >> 1))
		return false;

	sd = this_cpu_ptr(&softnet_data);

	rcu_read_lock();
	fl = rcu_dereference(sd->flow_limit);
	if (fl) {
		new_flow = skb_get_hash(skb) & (fl->num_buckets - 1);
		old_flow = fl->history[fl->history_head];
		fl->history[fl->history_head] = new_flow;

		fl->history_head++;
		fl->history_head &= FLOW_LIMIT_HISTORY - 1;

		if (likely(fl->buckets[old_flow]))
			fl->buckets[old_flow]--;

		if (++fl->buckets[new_flow] > (FLOW_LIMIT_HISTORY >> 1)) {

/* 학습 해설
 * 예외 테이블 복구: 실패한 명령 주소에서 재개 주소 찾기
 * 커널이 사용자 메모리처럼 실패할 수 있는 주소를 다룰 때 매 접근마다 큰 조건문을 실행하면 정상 경로가 복잡해집니다. 실패 가능한 명령 주소와 복구 경로를 별도 테이블에 등록해 실제 예외가 난 경우에만 찾아 처리할 수 있습니다.
 * fixup_exception은 저장된 regs->ip로 search_exception_tables를 호출하며 항목이 없으면0입니다. 있으면 data에서 type,reg,imm 필드를 추출해 handler로 분기합니다. 기본 handler는 CLEAR_AX/CLEAR_DX 플래그에 따라 저장 레지스터를0으로 하고 ip를 fixup 주소로 바꾼 뒤 true입니다. 처리할 수 없는 type은 함수 끝 BUG에 도달합니다.
 * 테이블의 fixup 필드가 위치한 주소가0x1000이고 저장 상대값이0x20이면 재개 주소는0x1020입니다. 기준은 fault 명령 주소가 아니라 &entry->fixup입니다. 저장된 ip를 바꾸므로 예외 복귀 후 같은 실패 명령을 무조건 재실행하는 방식과 다릅니다. ex_get_fixup_type은 같은 검색으로 type만 돌려주고 항목이 없으면 EX_TYPE_NONE입니다.
 */
int fixup_exception(struct pt_regs *regs, int trapnr, unsigned long error_code,
		    unsigned long fault_addr)
{
	const struct exception_table_entry *e;
	int type, reg, imm;

#ifdef CONFIG_PNPBIOS
	if (unlikely(SEGMENT_IS_PNP_CODE(regs->cs))) {
		extern u32 pnp_bios_fault_eip, pnp_bios_fault_esp;
		extern u32 pnp_bios_is_utter_crap;
		pnp_bios_is_utter_crap = 1;
		printk(KERN_CRIT "PNPBIOS fault.. attempting recovery.\n");
		__asm__ volatile(
			"movl %0, %%esp\n\t"
			"jmp *%1\n\t"
			: : "g" (pnp_bios_fault_esp), "g" (pnp_bios_fault_eip));
		panic("do_trap: can't hit this");
	}
#endif

	e = search_exception_tables(regs->ip);
	if (!e)
		return 0;

	type = FIELD_GET(EX_DATA_TYPE_MASK, e->data);
	reg  = FIELD_GET(EX_DATA_REG_MASK,  e->data);

/* 학습 해설
 * 페이지 경계의 Zeropad: 유효한 앞쪽 바이트만 읽어 복구하기
 * 경로 이름을 한 글자씩 읽는 대신 한 word씩 읽으면 빠르지만 마지막 짧은 문자열에서 다음 미매핑 페이지까지 읽으려 할 수 있습니다. 이 제한된 경우에는 이미 읽을 수 있는 앞 word에서 필요한 바이트를 꺼내고 나머지를0으로 만들어 계속할 수 있습니다.
 * handler는 fixup 주소와 현재 ip 차이로 명령 길이를 구하고 최대 길이,디코드 성공,정확한 디코드 길이를 검사합니다. opcode0x8b와 long 크기 피연산자만 허용합니다. 유효 주소를 얻고 long 정렬 기준으로 내린 뒤 fault_addr가 다음 word 시작인지 확인합니다. 목적지 레지스터를 찾아 정렬된 word를 offset*8만큼 오른쪽 이동해 저장하고 기본 복구로 갑니다.
 * 설명용8바이트 word에서 시작 offset이6이라면 정렬된 word를48비트 오른쪽으로 밀어 마지막2바이트만 낮은 위치에 남깁니다. unsigned long의 논리 이동으로 높은6바이트는0이 됩니다. 임의 명령이나 다른 fault 주소라면 false이므로 모든 미매핑 접근을0으로 채우는 일반 함수가 아닙니다.
 */
static bool ex_handler_zeropad(const struct exception_table_entry *e,
			       struct pt_regs *regs,
			       unsigned long fault_addr)
{
	struct insn insn;
	const unsigned long mask = sizeof(long) - 1;
	unsigned long offset, addr, next_ip, len;
	unsigned long *reg;

	next_ip = ex_fixup_addr(e);
	len = next_ip - regs->ip;
	if (len > MAX_INSN_SIZE)
		return false;

	if (insn_decode(&insn, (void *) regs->ip, len, INSN_MODE_KERN))
		return false;
	if (insn.length != len)
		return false;

	if (insn.opcode.bytes[0] != 0x8b)
		return false;
	if (insn.opnd_bytes != sizeof(long))
		return false;

	addr = (unsigned long) insn_get_addr_ref(&insn, regs);
	if (addr == ~0ul)

/* 학습 해설
 * MSR 예외 처리: 읽기0과 safe 오류 레지스터 구별
 * CPU의 모델별 레지스터 MSR은 지원하지 않거나 허용되지 않는 접근에서 예외가 날 수 있습니다. 실패한 읽기의 데이터와 오류 표시를 구분하지 않으면0이라는 결과를 실제 레지스터 값으로 오해할 수 있습니다.
 * ex_handler_msr는 safe가 아닌 쓰기/읽기에 각각 한 번 경고와 저장 스택 출력을 수행합니다. 읽기 실패이면 ax와 dx를0으로 합니다. safe이면 메타데이터가 지정한 레지스터에 -EIO를 쓰고 기본 handler로 재개합니다. 쓰기 실패에는 읽기처럼 ax/dx를0으로 하는 분기가 없습니다.
 * RDMSR_SAFE에서는 반환 데이터용 ax/dx가0이고 지정된 오류 레지스터는 -EIO가 됩니다. unchecked 읽기에서는0을 돌려주는 형태로 계속하며 경고가 단서입니다. unchecked 쓰기 경고는 cx의 MSR 번호와 dx:ax의 시도 값을 출력합니다. 경고가 매번 출력된다고 가정해서도 안 됩니다.
 */
static bool ex_handler_msr(const struct exception_table_entry *fixup,
			   struct pt_regs *regs, bool wrmsr, bool safe, int reg)
{
	if (__ONCE_LITE_IF(!safe && wrmsr)) {
		pr_warn("unchecked MSR access error: WRMSR to 0x%x (tried to write 0x%08x%08x) at rIP: 0x%lx (%pS)\n",
			(unsigned int)regs->cx, (unsigned int)regs->dx,
			(unsigned int)regs->ax,  regs->ip, (void *)regs->ip);
		show_stack_regs(regs);
	}

	if (__ONCE_LITE_IF(!safe && !wrmsr)) {
		pr_warn("unchecked MSR access error: RDMSR from 0x%x at rIP: 0x%lx (%pS)\n",
			(unsigned int)regs->cx, regs->ip, (void *)regs->ip);
		show_stack_regs(regs);
	}

	if (!wrmsr) {
		/* Pretend that the read succeeded and returned 0. */
		regs->ax = 0;
		regs->dx = 0;
	}

	if (safe)
		*pt_regs_nr(regs, reg) = -EIO;

	return ex_handler_default(fixup, regs);

/* 학습 해설
 * FPU 상태 복원 실패: 이전 태스크의 레지스터를 남기지 않기
 * 문맥 전환에서 새 태스크의 FPU 상태 복원이 실패했는데 이전 태스크의 레지스터가 그대로 남으면 다른 태스크의 정보가 노출될 수 있습니다. 실패 명령을 건너뛰는 것만으로는 충분하지 않고 안전한 초기 상태로 다시 설정하는 후속 처리가 필요합니다.
 * 이 handler는 regs->ip를 복구 주소로 먼저 바꿉니다. WARN_ONCE로 잘못된 FPU 상태를 알리고 fpu_reset_from_exception_fixup을 호출한 뒤 true입니다. 원문은 과거 ptrace나 sigreturn을 통해 XSAVE 예약 비트가 잘못 설정되어 XRSTOR가 실패했던 유형을 설명합니다. 여기서 초기 상태 복원은 별도 FPU helper가 담당합니다.
 * 태스크 A의 상태가 CPU에 남은 채 태스크 B의 복원만 실패한 경우를 생각하면 됩니다. handler는 B의 잘못된 저장 내용을 성공했다고 간주해 그대로 사용하지 않고 초기 상태로 리셋하는 경로를 실행합니다. 이것은 B의 원래 계산 결과를 보존하는 복구와는 목적이 다릅니다.
 */
static bool ex_handler_fprestore(const struct exception_table_entry *fixup,
				 struct pt_regs *regs)
{
	regs->ip = ex_fixup_addr(fixup);

	WARN_ONCE(1, "Bad FPU state detected at %pB, reinitializing FPU registers.",
		  (void *)instruction_pointer(regs));

	fpu_reset_from_exception_fixup();
	return true;
}

/*
 * On x86-64, we end up being imprecise with 'access_ok()', and allow
 * non-canonical user addresses to make the range comparisons simpler,
 * and to not have to worry about LAM being enabled.
 *
 * In fact, we allow up to one page of "slop" at the sign boundary,
 * which means that we can do access_ok() by just checking the sign
 * of the pointer for the common case of having a small access size.
 */
static bool gp_fault_address_ok(unsigned long fault_address)
{
#ifdef CONFIG_X86_64
	/* Is it in the "user space" part of the non-canonical space? */
	if (valid_user_address(fault_address))

/* 학습 해설
 * 초기 부팅 예외: 복구 실패와 WARN 명령 건너뛰기
 * 부팅 초반에는 일반 실행 환경이 완성되지 않아 예외 처리 자체가 다시 예외를 일으키는 상황도 고려해야 합니다. 모든 문제를 계속 실행으로 넘길 수 없으므로 복구 가능한 예외와 중단할 예외를 구분합니다.
 * early_fixup_exception은 NMI이면 즉시 반환합니다. early_recursion_flag>2이면 출력 없이 halt_loop로 갑니다. Xen PV가 아니면서 cs가 __KERNEL_CS와 다르면 fail입니다. 그 외에는 fixup_exception(regs,trapnr,orig_ax,0)을 시도하고 성공하면 반환합니다. 복구하지 못한 UD는 report_bug가 WARN 유형을 반환할 때만 ip에 LEN_UD2를 더해 계속합니다.
 * NMI가 아닌 예외에서 재귀 깊이 표시가3이면 예외 정보를 출력하는 경로마저 건너뛰고 halt를 반복합니다. 일반 UD가 WARN으로 판정되지 않으면 끝의 fail에서 예외 번호,CS:IP,오류,CR2를 출력하고 레지스터를 보여 준 뒤 무한 halt입니다. WARN을 건너뛰는 분기를 모든 잘못된 명령어를 무시하는 기능으로 생각하면 안 됩니다.
 */
void __init early_fixup_exception(struct pt_regs *regs, int trapnr)
{
	/* Ignore early NMIs. */
	if (trapnr == X86_TRAP_NMI)
		return;

	if (early_recursion_flag > 2)
		goto halt_loop;

	/*
	 * Old CPUs leave the high bits of CS on the stack
	 * undefined.  I'm not sure which CPUs do this, but at least
	 * the 486 DX works this way.
	 * Xen pv domains are not using the default __KERNEL_CS.
	 */
	if (!xen_pv_domain() && regs->cs != __KERNEL_CS)
		goto fail;

	/*
	 * The full exception fixup machinery is available as soon as
	 * the early IDT is loaded.  This means that it is the
	 * responsibility of extable users to either function correctly
	 * when handlers are invoked early or to simply avoid causing
	 * exceptions before they're ready to handle them.
	 *
	 * This is better than filtering which handlers can be used,
	 * because refusing to call a handler here is guaranteed to
	 * result in a hard-to-debug panic.
	 *
	 * Keep in mind that not all vectors actually get here.  Early
	 * page faults, for example, are special.
	 */

/* 학습 해설
 * 세그먼트 예외 분기: FS 초기화와 PNP BIOS 탈출 경로
 * 예외가 발생한 실행 문맥에 따라 일반 명령 재개보다 먼저 복구해야 할 CPU 상태가 다를 수 있습니다. FS 세그먼트 선택자 정리와 레거시 BIOS 호출에서의 스택 복원은 별개 계약이므로 같은 주소 fixup 하나로만 이해하면 놓치는 동작이 생깁니다.
 * ex_handler_clear_fs는 X86_BUG_NULL_SEG가 있으면 먼저 __USER_DS를 실제 FS 레지스터에 쓰고,그 여부와 무관하게0을 FS에 쓴 뒤 기본 handler로 갑니다. 여기의 FS는 파일시스템 약자가 아니라 x86 세그먼트 레지스터입니다. CONFIG_PNPBIOS의 dispatcher는 CS가 PNP 코드 세그먼트이면 일반 예외 테이블 검색 전에 특수 복구를 선택합니다.
 * NULL_SEG 특성이 없는 경우 FS 쓰기는0 한 번,있는 경우 __USER_DS 다음0 두 번입니다. PNP 경로는 실패 표시를1로 남기고 경고를 출력한 뒤 저장된 pnp_bios_fault_esp로 ESP를 복구하고 pnp_bios_fault_eip로 점프합니다. 그 뒤 C 코드의 panic은 도달하면 안 되는 경로의 방어이며 일반 true 반환으로 돌아오는 복구가 아닙니다.
 */
static bool ex_handler_clear_fs(const struct exception_table_entry *fixup,
				struct pt_regs *regs)
{
	if (static_cpu_has(X86_BUG_NULL_SEG))
		asm volatile ("mov %0, %%fs" : : "rm" (__USER_DS));
	asm volatile ("mov %0, %%fs" : : "rm" (0));
	return ex_handler_default(fixup, regs);
}

static bool ex_handler_imm_reg(const struct exception_table_entry *fixup,
			       struct pt_regs *regs, int reg, int imm)
{
	*pt_regs_nr(regs, reg) = (long)imm;
	return ex_handler_default(fixup, regs);
}

static bool ex_handler_ucopy_len(const struct exception_table_entry *fixup,
				  struct pt_regs *regs, int trapnr,
				  unsigned long fault_address,
				  int reg, int imm)
{
	regs->cx = imm * regs->cx + *pt_regs_nr(regs, reg);
	return ex_handler_uaccess(fixup, regs, trapnr, fault_address);
}

#ifdef CONFIG_X86_FRED

/* 학습 해설
 * 장치 깨우기 IRQ 연결: 기존 I/O 인터럽트의 소유권 보존
 * 인터럽트는 장치가 CPU에 사건을 알리는 신호입니다. 같은 I/O 신호를 절전 해제에도 사용하려면 장치의 전원 관리 정보와 IRQ 번호를 연결해야 합니다. 기존 드라이버가 등록한 처리기를 또 등록하거나 해제하면 원래 I/O 처리가 깨질 수 있으므로 연결 정보와 IRQ 자체의 소유권을 구별합니다.
 * dev_pm_set_wake_irq는 음수 번호를 -EINVAL로 거절하고 kzalloc으로 wake_irq를 만듭니다. 실패하면 -ENOMEM입니다. dev와 irq를 채운 뒤 attach를 호출하며, attach 실패 때 새 구조체만 해제합니다. attach는 NULL 입력을 거절하고 power.lock 아래 기존 wakeirq가 있으면 경고와 -EEXIST를 반환합니다. 없으면 장치 포인터를 설정하고 device_wakeup_attach_irq를 호출합니다.
 * 보통 probe에서 device_init_wakeup 이후 기존 I/O IRQ 번호를 연결합니다. 예를 들어 IRQ42가 이미 I/O용으로 등록돼 있다면 이 함수는 IRQ42용 새 request_threaded_irq를 호출하지 않습니다. wakeirq 연결이 이미 있는 장치에 두 번째 설정을 시도하면 기존 연결은 남고 새 할당만 정리됩니다. 유효한 장치의 수명과 드라이버 초기화 순서는 호출자가 지켜야 합니다.
 */
int dev_pm_set_wake_irq(struct device *dev, int irq)
{
	struct wake_irq *wirq;
	int err;

	if (irq < 0)
		return -EINVAL;

	wirq = kzalloc(sizeof(*wirq), GFP_KERNEL);
	if (!wirq)
		return -ENOMEM;

	wirq->dev = dev;
	wirq->irq = irq;

	err = dev_pm_attach_wake_irq(dev, wirq);
	if (err)
		kfree(wirq);

	return err;
}
EXPORT_SYMBOL_GPL(dev_pm_set_wake_irq);

/**
 * dev_pm_clear_wake_irq - Detach a device IO interrupt wake IRQ
 * @dev: Device entry
 *
 * Detach a device wake IRQ and free resources.
 *
 * Note that it's OK for drivers to call this without calling
 * dev_pm_set_wake_irq() as all the driver instances may not have
 * a wake IRQ configured. This avoid adding wake IRQ specific
 * checks into the drivers.
 */

/* 학습 해설
 * 전용 Wake IRQ 초기화: 실패한 단계까지만 되돌리기
 * 장치가 잠든 동안 일반 I/O 인터럽트를 사용할 수 없어 별도 깨우기 선을 제공하는 하드웨어가 있습니다. 이 경우 전용 처리기와 이름,연결 구조체가 필요합니다. 세 자원을 순서대로 얻다가 중간에 실패하면 이미 얻은 자원만 역순으로 반환해야 누수나 이중 해제를 피할 수 있습니다.
 * 함수는 음수 IRQ를 거절하고 구조체,장치명:wakeup 문자열 순서로 할당합니다. IRQ_DISABLE_UNLAZY를 설정한 뒤 기본 처리기 NULL과 전용 스레드 처리기를 IRQF_ONESHOT|IRQF_NO_AUTOEN으로 요청합니다. 장치에 attach까지 성공하면 status=DEDICATED_ALLOCATED|flag입니다. 이름 할당 실패는 구조체만,IRQ 요청 실패는 이름과 구조체,attach 실패는 IRQ·이름·구조체 순으로 정리합니다.
 * 일반 dev_pm_set_dedicated_wake_irq는 flag0,reverse 변형은 DEDICATED_REVERSE를 전달합니다. 하드웨어에 별도 wake IRQ가 있을 때 사용합니다. NO_AUTOEN은 등록 직후 자동 활성화를 막으므로 처리기 등록 성공이 곧 IRQ가 켜졌다는 뜻이 아닙니다. 예를 들어 attach가 -EEXIST이면 방금 요청한 전용 IRQ를 free_irq한 뒤 이름과 구조체를 해제하고 그 오류를 반환합니다.
 */
static int __dev_pm_set_dedicated_wake_irq(struct device *dev, int irq, unsigned int flag)
{
	struct wake_irq *wirq;
	int err;

	if (irq < 0)
		return -EINVAL;

	wirq = kzalloc(sizeof(*wirq), GFP_KERNEL);
	if (!wirq)
		return -ENOMEM;

	wirq->name = kasprintf(GFP_KERNEL, "%s:wakeup", dev_name(dev));
	if (!wirq->name) {
		err = -ENOMEM;
		goto err_free;
	}

	wirq->dev = dev;
	wirq->irq = irq;

	/* Prevent deferred spurious wakeirqs with disable_irq_nosync() */
	irq_set_status_flags(irq, IRQ_DISABLE_UNLAZY);

	/*
	 * Consumer device may need to power up and restore state
	 * so we use a threaded irq.
	 */

/* 학습 해설
 * Wake IRQ 스레드: 절전 중단 알림과 장치 복귀의 두 경로
 * 장치를 깨우려면 전원 공급기를 켜고 저장한 레지스터를 복원해야 할 수 있습니다. 이런 일을 매우 제한된 즉시 인터럽트 처리 문맥에 모두 밀어 넣기보다 스레드 처리기로 실행합니다. 또한 시스템 절전 전환에 알림을 보내는 일과 개별 장치를 runtime resume하는 일은 다른 경로입니다.
 * handler는 irq_get_irq_data로 IRQ 상태를 얻어 irqd_is_wakeup_set을 검사합니다. 설정돼 있으면 pm_wakeup_event(dev,0)를 호출하고 IRQ_HANDLED로 끝납니다. 그렇지 않으면 pm_runtime_resume을 동기 호출하며 음수 결과를 경고합니다. 이 경우도 반환값은 IRQ_HANDLED입니다. 원문은 RPM_ASYNC와 RPM_NOWAIT를 원하지 않는다고 명시합니다.
 * 같은 IRQ42라도 wakeup 상태가 설정된 호출은 이벤트 알림 후 종료하므로 이 분기에서 pm_runtime_resume을 실행하지 않습니다. 다른 호출에서 resume이 -5를 반환했다면 경고를 남기지만 IRQ 반환값은 여전히 HANDLED입니다. 그러므로 HANDLED만 세어 장치 복원이 전부 성공했다고 결론 내릴 수 없습니다.
 */
static irqreturn_t handle_threaded_wake_irq(int irq, void *_wirq)
{
	struct wake_irq *wirq = _wirq;
	int res;

	/* Maybe abort suspend? */
	if (irqd_is_wakeup_set(irq_get_irq_data(irq))) {
		pm_wakeup_event(wirq->dev, 0);

		return IRQ_HANDLED;
	}

	/* We don't want RPM_ASYNC or RPM_NOWAIT here */
	res = pm_runtime_resume(wirq->dev);
	if (res < 0)
		dev_warn(wirq->dev,
			 "wake IRQ with no resume: %i\n", res);

	return IRQ_HANDLED;
}

static int __dev_pm_set_dedicated_wake_irq(struct device *dev, int irq, unsigned int flag)
{
	struct wake_irq *wirq;
	int err;

/* 학습 해설
 * 첫 Runtime Suspend: Wake IRQ를 늦게 관리하는 이유
 * IRQ 비활성화는 단순히 bool을 false로 쓰는 것과 같다고 가정하면 안 됩니다. 처음부터 비활성인 IRQ를 장치의 첫 resume에서 또 비활성화하면 이후 enable과 짝이 어긋날 수 있습니다. 그래서 이 코드는 처음 suspend할 때부터 전용 IRQ의 관리 상태를 시작합니다.
 * wakeirq가 없거나 DEDICATED_MASK에 해당하지 않으면 반환합니다. 이미 MANAGED이면 enable 판단으로 갑니다. 아직 MANAGED가 아니면 can_change_status가 true일 때만 그 비트를 세우고 진행합니다. enable 단계에서는 !can_change_status 또는 !REVERSE일 때 enable_irq를 호출하고 ENABLED를 세웁니다. disable helper는 cond_disable&&REVERSE이면 반환하고,그 외에는 MANAGED일 때 ENABLED를 지우고 disable_irq_nosync를 호출합니다.
 * 일반 전용 IRQ의 최초 status는 ALLOCATED=1입니다. 첫 resume의 disable(false)는 MANAGED가 없어 아무 일도 하지 않습니다. 첫 정상 suspend의 enable_check(true)는 MANAGED=2를 더하고 실제 활성화 후 ENABLED=8을 더해 status11이 됩니다. 이후 resume의 disable(false)는 ENABLED만 내려 status3이 됩니다. 비트는 서로 독립된 사실을 압축해 표현합니다.
 */
void dev_pm_enable_wake_irq_check(struct device *dev,
				  bool can_change_status)
{
	struct wake_irq *wirq = dev->power.wakeirq;

	if (!wirq || !(wirq->status & WAKE_IRQ_DEDICATED_MASK))
		return;

	if (likely(wirq->status & WAKE_IRQ_DEDICATED_MANAGED)) {
		goto enable;
	} else if (can_change_status) {
		wirq->status |= WAKE_IRQ_DEDICATED_MANAGED;
		goto enable;
	}

	return;

enable:
	if (!can_change_status || !(wirq->status & WAKE_IRQ_DEDICATED_REVERSE)) {
		enable_irq(wirq->irq);
		wirq->status |= WAKE_IRQ_DEDICATED_ENABLED;
	}
}

/**
 * dev_pm_disable_wake_irq_check - Checks and disables wake-up interrupt
 * @dev: Device
 * @cond_disable: if set, also check WAKE_IRQ_DEDICATED_REVERSE
 *
 * Disables wake-up interrupt conditionally based on status.
 * Should be only called from rpm_suspend() and rpm_resume() path.
 */

/* 학습 해설
 * Reverse Wake IRQ 순서: Suspend 실패와 Resume 실패의 대칭 복구
 * 장치에 따라 suspend 콜백이 하드웨어를 정리한 뒤에야 깨우기 IRQ를 켜야 합니다. 너무 일찍 켜면 정리 중 발생한 신호를 깨우기 사건으로 받아들일 수 있습니다. 반대로 resume 실패로 다시 잠든 상태가 되면 IRQ를 복구해 다음 깨우기 기회를 남겨야 합니다.
 * REVERSE 경로는 enable_check(true)에서 MANAGED만 세우고 IRQ 활성화를 미룹니다. runtime_suspend 콜백이 성공하면 complete가 MANAGED&&REVERSE일 때 enable_irq하고 ENABLED를 세웁니다. 콜백 실패는 disable_check(true)로 가지만 REVERSE이면 건너뜁니다. 아직 켜지 않은 IRQ를 다시 끄지 않는 것입니다. resume 전 disable_check(false)는 reverse 여부와 무관하게 관리된 IRQ를 끄고,복귀 실패 때 enable_check(false)가 다시 켭니다.
 * reverse 초기 status5=ALLOCATED1|REVERSE4에서 suspend 시작은7,성공 후15,다음 resume 시작은7입니다. resume 실패 시 can_change_status=false이므로 REVERSE여도 enable 조건을 통과해15로 돌아옵니다. 첫 suspend 자체가 실패했다면7에 머물며 complete를 호출하지 않습니다. 일반 경로는 콜백 전에 켰으므로 suspend 실패 때 다시 끕니다.
 */
void dev_pm_enable_wake_irq_complete(struct device *dev)
{
	struct wake_irq *wirq = dev->power.wakeirq;

	if (!wirq || !(wirq->status & WAKE_IRQ_DEDICATED_MASK))
		return;

	if (wirq->status & WAKE_IRQ_DEDICATED_MANAGED &&
	    wirq->status & WAKE_IRQ_DEDICATED_REVERSE) {
		enable_irq(wirq->irq);
		wirq->status |= WAKE_IRQ_DEDICATED_ENABLED;
	}
}

/**
 * dev_pm_arm_wake_irq - Arm device wake-up
 * @wirq: Device wake-up interrupt
 *
 * Sets up the wake-up event conditionally based on the
 * device_may_wake().
 */
void dev_pm_arm_wake_irq(struct wake_irq *wirq)
{
	if (!wirq)
		return;

/* 학습 해설
 * 시스템 Wake IRQ 무장: 임시 Enable과 Runtime 상태 비트 분리
 * 개별 장치가 절전 중인 상태와 컴퓨터 전체가 잠드는 상태는 같지 않습니다. 시스템을 깨울 신호로 IRQ를 설정할 때,이미 runtime 관리가 켜 둔 IRQ인지 시스템 전환 때문에 잠깐 켠 IRQ인지 구별해야 복귀 후 원래 상태를 보존할 수 있습니다.
 * arm은 NULL이면 반환하고 device_may_wakeup일 때만 진행합니다. 전용 ALLOCATED이면서 runtime ENABLED가 없으면 enable_irq를 먼저 호출하고,이후 enable_irq_wake로 깨우기 기능을 설정합니다. disarm은 같은 허용 조건에서 disable_irq_wake를 먼저 호출하고,전용 ALLOCATED이면서 ENABLED가 없으면 disable_irq_nosync합니다. 이 두 helper는 ENABLED 비트를 변경하지 않습니다.
 * 예를 들어 status3인 전용 IRQ는 arm에서 잠시 enable되지만 status는3입니다. disarm은 ENABLED가 여전히 없다는 사실로 임시 enable을 되돌립니다. status11이면 runtime이 켜 둔 IRQ이므로 arm/disarm의 추가 enable/disable을 하지 않습니다. 기존 I/O 연결은 ALLOCATED가 없어 여기서는 wake 기능 설정·해제만 수행합니다. 이 예는 두 호출 사이 관련 정책과 runtime 상태가 유지되는 정상 전환을 가정합니다.
 */
void dev_pm_arm_wake_irq(struct wake_irq *wirq)
{
	if (!wirq)
		return;

	if (device_may_wakeup(wirq->dev)) {
		if (wirq->status & WAKE_IRQ_DEDICATED_ALLOCATED &&
		    !(wirq->status & WAKE_IRQ_DEDICATED_ENABLED))
			enable_irq(wirq->irq);

		enable_irq_wake(wirq->irq);
	}
}

/**
 * dev_pm_disarm_wake_irq - Disarm device wake-up
 * @wirq: Device wake-up interrupt
 *
 * Clears up the wake-up event conditionally based on the
 * device_may_wake().
 */
void dev_pm_disarm_wake_irq(struct wake_irq *wirq)
{
	if (!wirq)
		return;

/* 학습 해설
 * Discard 경계 맞추기: 파티션 시작과 바이트·섹터 단위
 * 파일시스템이 더 이상 쓰지 않는 영역을 장치에 알릴 때 요청 시작이 장치의 처리 단위 경계와 다를 수 있습니다. 첫 조각을 다음 경계까지만 만들면 이후 조각의 시작을 정렬할 수 있습니다. 이때 파티션 안의 상대 위치와 디스크 전체 위치를 혼동하면 잘못된 경계가 계산됩니다.
 * bio_discard_limit는 파티션이면 계산용 sector에 bd_start_sect를 더합니다. discard_granularity는 바이트이므로 SECTOR_SHIFT만큼 오른쪽 이동해 섹터 단위로 바꾼 뒤 round_up합니다. 현재 위치가 경계 전이면 다음 경계까지의 차이를 반환합니다. 이미 정렬됐으면 UINT_MAX를 바이트 granularity로 내려 맞춘 뒤 섹터로 바꿉니다.
 * 설명용 granularity4096바이트는512바이트 섹터8개입니다. 파티션 시작100,상대 sector2이면 계산 위치102,다음8경계104이므로 첫 조각 상한은2섹터입니다. 다음 상대 sector4는 전체 위치104가 됩니다. 실제 BIO의 bi_sector는 이 helper에서 계산한 전체 위치가 아니라 호출자가 가진 파티션 상대 위치로 설정됩니다.
 */
static sector_t bio_discard_limit(struct block_device *bdev, sector_t sector)
{
	unsigned int discard_granularity = bdev_discard_granularity(bdev);
	sector_t granularity_aligned_sector;

	if (bdev_is_partition(bdev))
		sector += bdev->bd_start_sect;

	granularity_aligned_sector =
		round_up(sector, discard_granularity >> SECTOR_SHIFT);

	/*
	 * Make sure subsequent bios start aligned to the discard granularity if
	 * it needs to be split.
	 */
	if (granularity_aligned_sector != sector)
		return granularity_aligned_sector - sector;

	/*
	 * Align the bio size to the discard granularity to make splitting the bio
	 * at discard granularity boundaries easier in the driver if needed.
	 */
	return round_down(UINT_MAX, discard_granularity) >> SECTOR_SHIFT;
}

struct bio *blk_alloc_discard_bio(struct block_device *bdev,

/* 학습 해설
 * Discard BIO 연결: 성공 반환과 장치 지원을 구분하기
 * 전체 디스크처럼 큰 영역은 BIO 하나의 크기 제한을 넘을 수 있습니다. 작은 BIO들을 완료 관계로 연결하면 앞 요청들을 제출하면서 마지막 요청을 통해 완료를 기다릴 수 있습니다. 하지만 오류를 의도적으로 바꾸는 wrapper에서는 반환0이 하드웨어 지원을 증명하지 않습니다.
 * blk_alloc_discard_bio는 남은 길이와 discard_limit의 작은 값을 선택합니다. 길이0 또는 bio_alloc 실패이면 NULL입니다. 성공하면 REQ_OP_DISCARD와 시작·바이트 크기를 설정하고 sector를 증가,nr_sects를 감소시킨 뒤 cond_resched합니다. __blkdev_issue_discard는 NULL이 나올 때까지 bio_chain_and_submit으로 연결하고0을 반환합니다. wrapper는 plug 안에서 마지막 BIO를 submit_bio_wait하고 -EOPNOTSUPP만0으로 바꾼 뒤 bio_put합니다.
 * 설명용 시작2,남은20에서 첫 조각2라면 다음 상태는 시작4,남은18입니다. A,B,C를 만들면 B를 붙일 때 A 제출,C를 붙일 때 B 제출이며 C는 wrapper가 제출하고 기다립니다. 요청이 지원되지 않았다는 -EOPNOTSUPP는 최종0으로 바뀌므로 반환0만 보고 discard가 실제로 수행됐다고 말할 수 없습니다.
 */
int blkdev_issue_discard(struct block_device *bdev, sector_t sector,
		sector_t nr_sects, gfp_t gfp_mask)
{
	struct bio *bio = NULL;
	struct blk_plug plug;
	int ret;

	blk_start_plug(&plug);
	ret = __blkdev_issue_discard(bdev, sector, nr_sects, gfp_mask, &bio);
	if (!ret && bio) {
		ret = submit_bio_wait(bio);
		if (ret == -EOPNOTSUPP)
			ret = 0;
		bio_put(bio);
	}
	blk_finish_plug(&plug);

	return ret;
}
EXPORT_SYMBOL(blkdev_issue_discard);

static sector_t bio_write_zeroes_limit(struct block_device *bdev)
{
	sector_t bs_mask = (bdev_logical_block_size(bdev) >> 9) - 1;

	return min(bdev_write_zeroes_sectors(bdev),

/* 학습 해설
 * WRITE ZEROES 분할: 32비트 바이트 길이와 논리 블록 정렬
 * 장치가 직접0 채우기를 지원하면 큰0 버퍼를 매번 전송하지 않고 범위 명령을 보낼 수 있습니다. 그래도 장치가 받는 최대 섹터 수와 BIO가 표현하는 바이트 길이는 제한돼 있습니다. 두 제한 중 작은 값을 써야 넘침이나 장치 한도 초과를 피합니다.
 * bio_write_zeroes_limit는 논리 블록 크기를512바이트 섹터 수로 바꿔 bs_mask를 만들고,UINT_MAX>>SECTOR_SHIFT를 ~bs_mask로 내려 맞춥니다. 이 값과 장치의 write_zeroes 한도 중 작은 값을 반환합니다. 내부 발행 루프는 남은 섹터와 limit 중 작은 len으로 REQ_OP_WRITE_ZEROES BIO를 만들며,NOUNMAP이면 REQ_NOUNMAP을 추가합니다. 섹터·잔여 길이를 갱신하고 cond_resched합니다.
 * 논리 블록4096바이트면 bs_mask7입니다. UINT_MAX>>9는8388607이고 하위3비트를 지우면8388600섹터입니다. 장치 한도1024이면 실제 limit1024입니다. 총2056섹터는1024+1024+8로 나눌 수 있습니다. NOUNMAP은0 채우기 과정에서 하부 공간을 해제하지 않도록 요청하는 플래그이며 모든 물리 매체의 삭제 보증과 같지 않습니다.
 */
static sector_t bio_write_zeroes_limit(struct block_device *bdev)
{
	sector_t bs_mask = (bdev_logical_block_size(bdev) >> 9) - 1;

	return min(bdev_write_zeroes_sectors(bdev),
		(UINT_MAX >> SECTOR_SHIFT) & ~bs_mask);
}

/*
 * There is no reliable way for the SCSI subsystem to determine whether a
 * device supports a WRITE SAME operation without actually performing a write
 * to media. As a result, write_zeroes is enabled by default and will be
 * disabled if a zeroing operation subsequently fails. This means that this
 * queue limit is likely to change at runtime.
 */
static void __blkdev_issue_write_zeroes(struct block_device *bdev,
		sector_t sector, sector_t nr_sects, gfp_t gfp_mask,
		struct bio **biop, unsigned flags, sector_t limit)
{

	while (nr_sects) {
		unsigned int len = min(nr_sects, limit);
		struct bio *bio;

		if ((flags & BLKDEV_ZERO_KILLABLE) &&
		    fatal_signal_pending(current))

/* 학습 해설
 * 0 채우기 중단: 제출된 BIO를 기다리고 마지막 BIO는 끝내기
 * 긴 디스크 작업 중 프로세스에 치명적인 신호가 도착하면 남은 작업 생성을 멈추고 싶습니다. 이미 제출한 I/O가 존재하는데 즉시 메모리를 없애면 완료 경로가 해제된 자료를 만질 수 있습니다. 따라서 미제출 마지막 요청과 이미 제출한 앞 요청을 다르게 처리합니다.
 * write_zeroes wrapper는 내부 루프 뒤 BIO가 있으면 KILLABLE과 fatal_signal_pending을 다시 검사합니다. 참이면 bio_await_chain으로 마지막 BIO를 종료하고 연결된 앞 요청들의 완료를 기다린 뒤 plug를 끝내고 -EINTR입니다. 정상 경로는 마지막 BIO를 submit_bio_wait하고 bio_put합니다. 오류가 있고 장치의 write_zeroes 한도가0으로 바뀌었으면 -EOPNOTSUPP로 바꿉니다.
 * A가 제출됐고 B가 마지막 미제출 BIO일 때 중단되면 bio_await_chain(B)는 B를 디스크에 새로 제출하지 않습니다. B 자신의 완료를 표시하고 A를 기다립니다. A가 쓴 부분을 되돌리지는 않으므로 -EINTR은 전체 범위가 그대로라는 뜻이 아닙니다. 첫 BIO도 만들기 전에 신호로 멈춰 bio가 NULL이면 이 wrapper의 if(bio)를 통과하지 않아 초기 ret0을 반환하는 경로도 있습니다.
 */
static int blkdev_issue_write_zeroes(struct block_device *bdev, sector_t sector,
		sector_t nr_sects, gfp_t gfp, unsigned flags)
{
	sector_t limit = bio_write_zeroes_limit(bdev);
	struct bio *bio = NULL;
	struct blk_plug plug;
	int ret = 0;

	blk_start_plug(&plug);
	__blkdev_issue_write_zeroes(bdev, sector, nr_sects, gfp, &bio,
			flags, limit);
	if (bio) {
		if ((flags & BLKDEV_ZERO_KILLABLE) &&
		    fatal_signal_pending(current)) {
			bio_await_chain(bio);
			blk_finish_plug(&plug);
			return -EINTR;
		}
		ret = submit_bio_wait(bio);
		bio_put(bio);
	}
	blk_finish_plug(&plug);

	/*
	 * For some devices there is no non-destructive way to verify whether
	 * WRITE ZEROES is actually supported.  These will clear the capability
	 * on an I/O error, in which case we'll turn any error into
	 * "not supported" here.
	 */

/* 학습 해설
 * ZERO_PAGE fallback: 같은0 페이지를 여러 저장 위치에 쓰기
 * 장치가 범위0 채우기 명령을 지원하지 않아도 일반 쓰기로0 데이터를 보낼 수 있습니다. 영역 크기만큼 새로운0 버퍼를 할당하면 메모리가 낭비되므로 이미0인 페이지를 데이터 원본으로 여러 BIO 조각에 참조합니다. 쓰이는 디스크 위치는 진행해도 원본 페이지는 재사용할 수 있습니다.
 * __blkdev_sectors_to_bio_pages는 섹터 수를 페이지당 섹터 수로 올림 나누고 BIO_MAX_VECS로 제한합니다. 내부 루프는 REQ_OP_WRITE BIO를 만들고 ZERO_PAGE(0)의 offset0에서 min(PAGE_SIZE,남은 바이트)를 bio_add_page합니다. 추가량이 요청 len보다 작으면 현재 BIO 채우기를 멈춥니다. 전량 추가됐을 때만 남은 섹터와 다음 sector를 갱신하고 BIO를 chain에 붙입니다.
 * PAGE_SIZE4096,남은10섹터라면 ceil(10/8)=2개의 벡터 용량을 요청합니다. 첫4096바이트로8섹터,다음1024바이트로2섹터를 채웁니다. 두 번 모두 ZERO_PAGE의 offset0에서 읽어도0 데이터이므로 문제없습니다. 페이지 수 helper에0을 주면 계산 결과0이며 주석의 최소1 설명은0보다 큰 짧은 요청에 해당합니다.
 */
static void __blkdev_issue_zero_pages(struct block_device *bdev,
		sector_t sector, sector_t nr_sects, gfp_t gfp_mask,
		struct bio **biop, unsigned int flags)
{
	while (nr_sects) {
		unsigned int nr_vecs = __blkdev_sectors_to_bio_pages(nr_sects);
		struct bio *bio;

		bio = bio_alloc(bdev, nr_vecs, REQ_OP_WRITE, gfp_mask);
		bio->bi_iter.bi_sector = sector;

		if ((flags & BLKDEV_ZERO_KILLABLE) &&
		    fatal_signal_pending(current))
			break;

		do {
			unsigned int len, added;

			len = min_t(sector_t,
				PAGE_SIZE, nr_sects << SECTOR_SHIFT);
			added = bio_add_page(bio, ZERO_PAGE(0), len, 0);
			if (added < len)
				break;
			nr_sects -= added >> SECTOR_SHIFT;
			sector += added >> SECTOR_SHIFT;
		} while (nr_sects);

/* 학습 해설
 * Zeroout API 선택: 비동기 생성과 동기 Fallback의 차이
 * 범위0 채우기를 요청하는 상위 코드는 단순 완료 결과를 원할 수도 있고 기존 BIO chain에 작업을 이어 붙이고 싶을 수도 있습니다. 이름 앞의 밑줄만 보고 같은 검증과 실패 대체 동작이라고 가정하면 정렬되지 않은 요청이나 완료 오류를 놓칩니다.
 * 동기 blkdev_issue_zeroout은 (sector|nr_sects)&bs_mask로 시작·길이 정렬을 검사하고 -EINVAL,그다음 읽기 전용이면 -EPERM입니다. 장치 write_zeroes 한도가 있으면 명령 경로를 시도하고 결과가 -EOPNOTSUPP일 때만 zero_pages로 갑니다. __blkdev_issue_zeroout은 읽기 전용을 검사하고 계산한 limit에 따라 BIO를 생성하지만 이 함수 안에는 같은 정렬 검사나 제출 완료 후 fallback이 없습니다.
 * 논리 블록4096바이트에서는 시작16,길이24가 모두8의 배수여서 통과합니다. 시작17이면 하위3비트가 남아 -EINVAL입니다. 동기 명령이 -EIO이고 지원 한도가 유지되면 그대로 반환하고,지원 한도가 실패 후0으로 바뀌어 -EOPNOTSUPP가 되면 일반 쓰기를 시도할 수 있습니다. NOFALLBACK이면 그 대체도 -EOPNOTSUPP로 거절합니다.
 */
int blkdev_issue_zeroout(struct block_device *bdev, sector_t sector,
		sector_t nr_sects, gfp_t gfp_mask, unsigned flags)
{
	int ret;

	if ((sector | nr_sects) & ((bdev_logical_block_size(bdev) >> 9) - 1))
		return -EINVAL;
	if (bdev_read_only(bdev))
		return -EPERM;

	if (bdev_write_zeroes_sectors(bdev)) {
		ret = blkdev_issue_write_zeroes(bdev, sector, nr_sects,
				gfp_mask, flags);
		if (ret != -EOPNOTSUPP)
			return ret;
	}

	return blkdev_issue_zero_pages(bdev, sector, nr_sects, gfp_mask, flags);
}
EXPORT_SYMBOL(blkdev_issue_zeroout);

int blkdev_issue_secure_erase(struct block_device *bdev, sector_t sector,
		sector_t nr_sects, gfp_t gfp)
{
	sector_t bs_mask = (bdev_logical_block_size(bdev) >> 9) - 1;
	unsigned int max_sectors = bdev_max_secure_erase_sectors(bdev);

/* 학습 해설
 * Secure Erase 범위 분할: 지원·정렬·읽기 전용 검사의 순서
 * 보안 삭제 명령도 장치별 최대 요청 크기와 논리 블록 경계를 지켜야 합니다. 큰 범위를 한 명령에 담지 못하면 작은 범위로 나누되,오류와 완료를 연결해 상위 호출자에게 결과를 돌려줍니다. 여기서 요청을 발행하는 코드와 장치 내부의 삭제 보증은 서로 다른 검토 범위입니다.
 * 함수는 장치 max_secure_erase_sectors를 UINT_MAX>>SECTOR_SHIFT 이하로 제한하고 ~bs_mask로 내려 정렬합니다. 결과0이면 -EOPNOTSUPP,시작 또는 길이 정렬 위반이면 -EINVAL,읽기 전용이면 -EPERM입니다. plug 안에서 min(잔여,max) 길이의 REQ_OP_SECURE_ERASE BIO를 blk_next_bio로 연결하며,마지막 BIO를 submit_bio_wait하고 bio_put한 뒤 plug를 끝냅니다.
 * 장치 최대19섹터,논리 블록8섹터이면 사용할 최대는16입니다. 정렬된40섹터 요청은16+16+8로 분할됩니다. 최대 한도가7이면 정렬 후0이므로 지원 불가로 처리합니다. 지원 불가이면서 읽기 전용인 경우 먼저 -EOPNOTSUPP를 반환하며,검사 순서가 관찰 가능한 오류를 결정합니다.
 */
int blkdev_issue_secure_erase(struct block_device *bdev, sector_t sector,
		sector_t nr_sects, gfp_t gfp)
{
	sector_t bs_mask = (bdev_logical_block_size(bdev) >> 9) - 1;
	unsigned int max_sectors = bdev_max_secure_erase_sectors(bdev);
	struct bio *bio = NULL;
	struct blk_plug plug;
	int ret = 0;

	/* make sure that "len << SECTOR_SHIFT" doesn't overflow */
	if (max_sectors > UINT_MAX >> SECTOR_SHIFT)
		max_sectors = UINT_MAX >> SECTOR_SHIFT;
	max_sectors &= ~bs_mask;

	if (max_sectors == 0)
		return -EOPNOTSUPP;
	if ((sector | nr_sects) & bs_mask)
		return -EINVAL;
	if (bdev_read_only(bdev))
		return -EPERM;

	blk_start_plug(&plug);
	while (nr_sects) {
		unsigned int len = min_t(sector_t, nr_sects, max_sectors);

		bio = blk_next_bio(bio, bdev, 0, REQ_OP_SECURE_ERASE, gfp);

/* 학습 해설
 * UTS 이름 격리: 같은 포인터 공유와 새 이름 복사
 * 컨테이너마다 다른 호스트 이름을 보여 주려면 이름을 모든 프로세스가 하나로 공유하는 전역 문자열에만 두면 안 됩니다. Linux는 태스크가 참조하는 UTS namespace 객체 안에 이름을 둡니다. 새 객체를 만들지 않는 경우에는 같은 이름을 공유하고 새 객체를 만들면 이후 변경이 분리됩니다.
 * copy_utsname은 old_ns가 NULL이면 BUG_ON이며 먼저 get_uts_ns로 참조를 얻습니다. CLONE_NEWUTS가 없으면 그 old_ns를 그대로 반환합니다. 플래그가 있으면 clone_uts_ns로 새 객체를 만든 뒤 old_ns의 임시 참조를 put하고 새 포인터 또는 오류 포인터를 반환합니다. clone은 uts_sem 읽기 잠금 아래 name 구조체를 memcpy하므로 처음 이름 값은 원본과 같습니다.
 * 원래 객체 참조 수가3이면 공유 경로는4가 된 같은 객체를 반환합니다. 새 namespace 경로는 원본을 잠시4로 했다가3으로 되돌리고 새 객체 참조1을 반환합니다. 이름 server-a로 복제한 후 한쪽 이름을 server-b로 바꾸면 분리된 name 저장 공간 때문에 다른 쪽은 server-a를 유지합니다. 복제 실패도 원본의 임시 참조는 내려갑니다.
 */
struct uts_namespace *copy_utsname(unsigned long flags,
	struct user_namespace *user_ns, struct uts_namespace *old_ns)
{
	struct uts_namespace *new_ns;

	BUG_ON(!old_ns);
	get_uts_ns(old_ns);

	if (!(flags & CLONE_NEWUTS))
		return old_ns;

	new_ns = clone_uts_ns(user_ns, old_ns);

	put_uts_ns(old_ns);
	return new_ns;
}

void free_uts_ns(struct uts_namespace *ns)
{
	dec_uts_namespaces(ns->ucounts);
	put_user_ns(ns->user_ns);
	ns_free_inum(&ns->ns);
	kmem_cache_free(uts_ns_cache, ns);
}

static inline struct uts_namespace *to_uts_ns(struct ns_common *ns)

/* 학습 해설
 * UTS 생성 제한: 사용자별 개수 회계와 역순 실패 정리
 * 프로세스가 namespace를 무한히 만들면 커널 객체와 식별 번호를 계속 소비합니다. 객체 메모리 할당만 검사해서는 사용자별 생성 제한을 지킬 수 없으므로 먼저 개수 회계의 몫을 얻습니다. 그 뒤 단계가 실패하면 회계까지 돌려놓아야 실패한 생성이 할당량을 영구 소비하지 않습니다.
 * clone_uts_ns는 inc_uts_namespaces(user_ns)로 current_euid의 UCOUNT_UTS_NAMESPACES를 증가시킵니다. 실패하면 -ENOSPC 오류 포인터입니다. 다음 create_uts_ns는 slab 객체를 할당하고 참조 수1로 초기화하며 실패는 -ENOMEM입니다. ns_alloc_inum 실패면 그 오류를 보존하고 객체를 해제한 뒤 회계를 감소시킵니다. 성공하면 ucounts와 operations를 설정하고 이름 복사와 get_user_ns를 수행합니다.
 * 예를 들어 회계가 허용한 몫 하나를 얻었지만 객체 할당이 실패하면 fail_dec에서 그 몫을 반납합니다. 식별 번호 할당까지 실패했으면 fail_free에서 객체를 먼저 반납하고 fail_dec로 내려갑니다. 원문 주석의 ENOMEM만 읽으면 첫 단계 ENOSPC와 ns_alloc_inum의 다른 오류를 놓칩니다. 반환값은 NULL과 다르게 ERR_PTR(err)이므로 호출자는 오류 포인터 규약으로 확인해야 합니다.
 */
static struct uts_namespace *clone_uts_ns(struct user_namespace *user_ns,
					  struct uts_namespace *old_ns)
{
	struct uts_namespace *ns;
	struct ucounts *ucounts;
	int err;

	err = -ENOSPC;
	ucounts = inc_uts_namespaces(user_ns);
	if (!ucounts)
		goto fail;

	err = -ENOMEM;
	ns = create_uts_ns();
	if (!ns)
		goto fail_dec;

	err = ns_alloc_inum(&ns->ns);
	if (err)
		goto fail_free;

	ns->ucounts = ucounts;
	ns->ns.ops = &utsns_operations;

	down_read(&uts_sem);
	memcpy(&ns->name, &old_ns->name, sizeof(ns->name));

/* 학습 해설
 * UTS namespace 교체: 권한 두 곳과 먼저 얻고 나중에 놓기
 * 다른 namespace에 들어가면 프로세스가 보는 이름과 그 이름을 관리하는 권한 관계가 바뀝니다. 대상만 검사하고 호출자 쪽 권한을 무시해서는 안 됩니다. 또한 새 객체가 기존 객체와 같을 수 있어 교체 과정의 참조 순서를 잘못 잡으면 사용하는 객체를 먼저 해제할 수 있습니다.
 * utsns_install은 new의 ns_common에서 container_of로 uts_namespace를 찾습니다. 대상 ns->user_ns와 nsset->cred->user_ns 양쪽에 대해 CAP_SYS_ADMIN을 검사하며 하나라도 실패하면 -EPERM입니다. 성공하면 대상 get_uts_ns를 먼저 호출하고 nsproxy의 기존 uts_ns를 put한 뒤 새 포인터를 대입하고0을 반환합니다. 작업 대상은 인자로 받은 nsset의 nsproxy입니다.
 * 대상과 기존이 같은 객체이며 참조 수가1인 예를 보면 get으로2,put으로1이 된 뒤 같은 포인터가 남습니다. 반대로 기존을 먼저 put하면0이 되어 해제될 수 있으므로 순서가 중요합니다. 두 권한 검사 중 하나가 실패하면 get/put/대입을 하기 전에 반환하므로 이 함수는 기존 연결을 유지합니다.
 */
static int utsns_install(struct nsset *nsset, struct ns_common *new)
{
	struct nsproxy *nsproxy = nsset->nsproxy;
	struct uts_namespace *ns = to_uts_ns(new);

	if (!ns_capable(ns->user_ns, CAP_SYS_ADMIN) ||
	    !ns_capable(nsset->cred->user_ns, CAP_SYS_ADMIN))
		return -EPERM;

	get_uts_ns(ns);
	put_uts_ns(nsproxy->uts_ns);
	nsproxy->uts_ns = ns;
	return 0;
}

static struct user_namespace *utsns_owner(struct ns_common *ns)
{
	return to_uts_ns(ns)->user_ns;
}

const struct proc_ns_operations utsns_operations = {
	.name		= "uts",
	.type		= CLONE_NEWUTS,
	.get		= utsns_get,
	.put		= utsns_put,
	.install	= utsns_install,

/* 학습 해설
 * UTS 조회와 전용 Slab: 태스크 잠금 안에서 참조 얻기
 * 다른 태스크의 namespace 포인터를 읽고 잠금을 풀어 버린 뒤 참조를 얻으면 그 사이 태스크의 연결이 사라질 수 있습니다. 안전한 조회는 연결을 보호하는 잠금 아래에서 포인터를 읽고 객체 참조까지 확보해야 합니다. 자주 생성되는 고정 크기 객체는 별도 slab cache로 관리합니다.
 * utsns_get은 task_lock 안에서 task->nsproxy를 읽습니다. 있으면 uts_ns를 가져와 get_uts_ns한 뒤 task_unlock하고 &ns->ns를 반환합니다. nsproxy가 없으면 NULL입니다. utsns_put은 공통 포인터를 바깥 객체로 변환해 put합니다. uts_ns_init은 kmem_cache_create_usercopy로 uts_namespace 크기의 cache를 만들고 SLAB_PANIC|SLAB_ACCOUNT,허용 복사 구간으로 name의 offset과 크기를 전달합니다.
 * 태스크가 namespace N을 가리키고 있을 때 조회가 잠금 안에서 N의 참조를1에서2로 올리면 이후 태스크 쪽 참조를 내려도 조회자가 가진 하나가 남습니다. 조회자가 utsns_put을 해야 마지막 수명 정리가 가능합니다. name은65바이트 배열6개로390바이트이며,user_ns 포인터나 참조 수 같은 관리 필드까지 usercopy 허용 구간으로 지정한 것이 아닙니다.
 */
static struct ns_common *utsns_get(struct task_struct *task)
{
	struct uts_namespace *ns = NULL;
	struct nsproxy *nsproxy;

	task_lock(task);
	nsproxy = task->nsproxy;
	if (nsproxy) {
		ns = nsproxy->uts_ns;
		get_uts_ns(ns);
	}
	task_unlock(task);

	return ns ? &ns->ns : NULL;
}

static void utsns_put(struct ns_common *ns)
{
	put_uts_ns(to_uts_ns(ns));
}

static int utsns_install(struct nsset *nsset, struct ns_common *new)
{
	struct nsproxy *nsproxy = nsset->nsproxy;
	struct uts_namespace *ns = to_uts_ns(new);

/* 학습 해설
 * IPC namespace 생성 재시도: 아직 반납되지 않은 생성 몫 기다리기
 * IPC namespace를 쓰던 마지막 태스크가 나갔다고 관련 메시지 큐와 마운트가 즉시 모두 해제되는 것은 아닙니다. 정리를 작업 큐로 미루면 사용자별 생성 몫도 늦게 반납됩니다. 새 생성에서 한도 초과가 보일 때 실제 부족인지 대기 중인 정리가 있는지 구별할 필요가 있습니다.
 * create_ipc_ns는 current_euid와 user namespace를 대상으로 UCOUNT_IPC_NAMESPACES를 증가시킵니다. 몫을 못 얻으면 free_ipc_work를 flush합니다. 기다릴 정리 작업이 있어 flush_work가 true이면 again으로 돌아가 회계를 재시도합니다. false이면 -ENOSPC 오류 포인터로 끝납니다. 몫을 얻으면 GFP_KERNEL_ACCOUNT로0 초기화한 객체를 할당하고 namespace 번호·참조1·user_ns 참조·ucounts를 설정합니다.
 * 예를 들어 한도10개 중10개가 회계에 잡혔지만 그중2개가 지연 해제 중이면 정리 완료 후8개가 되어 재시도가 성공할 수 있습니다. 기다렸다고 반드시 두 자리가 생기는 것은 아니므로 코드는 회계 획득을 다시 수행합니다. 현재 한도를 임의로 높이거나 이름만 바꿔 회피하는 방식이 아닙니다. 정리할 일이 없으면 같은 실패를 무한 반복하지 않습니다.
 */
static struct ipc_namespace *create_ipc_ns(struct user_namespace *user_ns,
					   struct ipc_namespace *old_ns)
{
	struct ipc_namespace *ns;
	struct ucounts *ucounts;
	int err;

	err = -ENOSPC;
 again:
	ucounts = inc_ipc_namespaces(user_ns);
	if (!ucounts) {
		/*
		 * IPC namespaces are freed asynchronously, by free_ipc_work.
		 * If frees were pending, flush_work will wait, and
		 * return true. Fail the allocation if no frees are pending.
		 */
		if (flush_work(&free_ipc_work))
			goto again;
		goto fail;
	}

	err = -ENOMEM;
	ns = kzalloc(sizeof(struct ipc_namespace), GFP_KERNEL_ACCOUNT);
	if (ns == NULL)
		goto fail_dec;

/* 학습 해설
 * IPC 초기화 실패 경로: 정상 파괴 함수와 같은지 직접 대조하기
 * 여러 하위 기능을 가진 객체를 만들 때는 몇 번째 단계까지 성공했는지에 따라 정리할 자원이 달라집니다. 실패 레이블이 있다는 사실만으로 모든 획득 자원이 되돌려진다고 가정하면 안 됩니다. 정상 종료 함수와 실패 경로를 각각 읽어 실제 정리 호출의 유무를 비교해야 합니다.
 * create_ipc_ns는 mq_init_ns,setup_mq_sysctls,setup_ipc_sysctls,msg_init_ns,sem_init_ns,shm_init_ns 순으로 진행합니다. MQ sysctl 준비 실패는 fail_put,IPC sysctl 준비 실패는 fail_mq에서 MQ sysctl을 retire한 뒤 fail_put입니다. msg_init_ns 실패도 fail_put입니다. fail_put은 user_ns 참조와 namespace 번호를 놓고,아래에서 객체와 생성 몫을 반납합니다.
 * mq_init_ns가 성공하면 mq_mnt에 마운트가 저장됩니다. 그러나 이 고정 원문의 생성 실패 레이블에는 mntput(ns->mq_mnt)가 없습니다. 또한 msg_init_ns 실패 분기에는 이미 준비한 두 sysctl을 retire하는 호출이 없습니다. 정상 free_ipc_ns에는 마운트·하위 IPC·두 sysctl 정리가 있습니다. 따라서 실패를 모두 정상 파괴와 동일하게 정리한다고 설명하면 잘못입니다.
 */
struct ipc_namespace *copy_ipcs(unsigned long flags,
	struct user_namespace *user_ns, struct ipc_namespace *ns)
{
	if (!(flags & CLONE_NEWIPC))
		return get_ipc_ns(ns);
	return create_ipc_ns(user_ns, ns);
}

/*
 * free_ipcs - free all ipcs of one type
 * @ns:   the namespace to remove the ipcs from
 * @ids:  the table of ipcs to free
 * @free: the function called to free each individual ipc
 *
 * Called for each kind of ipc when an ipc_namespace exits.
 */
void free_ipcs(struct ipc_namespace *ns, struct ipc_ids *ids,
	       void (*free)(struct ipc_namespace *, struct kern_ipc_perm *))
{
	struct kern_ipc_perm *perm;
	int next_id;
	int total, in_use;

	down_write(&ids->rwsem);

	in_use = ids->in_use;

/* 학습 해설
 * 희소 IPC 번호 해제: 인덱스 수와 살아 있는 객체 수 구분
 * IPC 객체 번호가0,100처럼 듬성듬성 남으면 객체가2개라고 인덱스0과1만 검사해서는 모두 찾을 수 없습니다. 반대로 빈 번호까지 객체 수로 세면 종료 조건이 잘못됩니다. 이 함수는 검색할 번호와 실제로 해제한 객체 개수를 따로 유지합니다.
 * free_ipcs는 ids->rwsem 쓰기 잠금을 잡고 시작 시 ids->in_use를 저장합니다. next_id는0부터 매 반복 증가하고 idr_find가 NULL이면 continue합니다. 객체를 찾았을 때만 rcu_read_lock과 ipc_lock_object를 얻고 타입별 free 콜백을 부른 뒤 total을 증가시킵니다. total이 시작 객체 수에 도달하면 반복을 끝내고 rwsem을 풉니다.
 * 살아 있는 번호가0과100이면 in_use2입니다. 번호0에서 total1,번호1부터99까지는 계속1,번호100을 해제한 뒤2가 되어 끝납니다. 원문은 이 루프에서 다음 존재 번호로 바로 건너뛰는 IDR iterator를 사용하지 않으므로 빈 번호 검색 비용도 생깁니다. in_use와 실제 테이블 내용이 일치하고 종료 중 테이블이 적절히 보호된다는 계약이 필요합니다.
 */
void free_ipcs(struct ipc_namespace *ns, struct ipc_ids *ids,
	       void (*free)(struct ipc_namespace *, struct kern_ipc_perm *))
{
	struct kern_ipc_perm *perm;
	int next_id;
	int total, in_use;

	down_write(&ids->rwsem);

	in_use = ids->in_use;

	for (total = 0, next_id = 0; total < in_use; next_id++) {
		perm = idr_find(&ids->ipcs_idr, next_id);
		if (perm == NULL)
			continue;
		rcu_read_lock();
		ipc_lock_object(perm);
		free(ns, perm);
		total++;
	}
	up_write(&ids->rwsem);
}

static void free_ipc_ns(struct ipc_namespace *ns)
{
	/*
	 * Caller needs to wait for an RCU grace period to have passed
	 * after making the mount point inaccessible to new accesses.
	 */

/* 학습 해설
 * IPC 지연 파괴: 마지막 참조와 RCU 대기를 작업 큐로 옮기기
 * 마지막 태스크가 나가더라도 다른 mount namespace에서 같은 mqueue 파일시스템을 통해 IPC namespace에 접근할 수 있습니다. 참조를0으로 내리는 순간과 파일시스템 경유 참조 획득을 조정해야 해제 중인 객체가 다시 사용되지 않습니다. 비싼 RCU 대기는 여러 객체를 모아 작업 큐에서 처리합니다.
 * put_ipc_ns는 refcount_dec_and_lock으로 마지막 참조일 때 mq_lock을 얻습니다. mq_clear_sbinfo로 마운트 superblock의 s_fs_info를 NULL로 만들어 연결을 끊고 잠금을 놓습니다. 객체를 free_ipc_list에 llist_add하며 이전 목록이 비어 있었다면 작업을 예약합니다. worker는 llist_del_all로 한 묶음을 떼고 각 마운트를 shortterm으로 바꾼 뒤 synchronize_rcu 한 번을 기다려 그 묶음을 free_ipc_ns로 정리합니다.
 * A,B,C가 같은 worker 묶음에 들어왔다면 각각 따로 RCU 유예를 기다리는 대신 묶음의 마지막 사용자들을 한 번 기다립니다. worker가 목록을 떼어 낸 뒤 추가된 D는 이미 떼어 둔 A,B,C 순회에 저절로 포함되지 않습니다. llist와 workqueue의 예약 계약이 다음 처리를 이어 줍니다. 참조0은 kfree가 이미 끝났다는 관찰값이 아닙니다.
 */
void put_ipc_ns(struct ipc_namespace *ns)
{
	if (refcount_dec_and_lock(&ns->ns.count, &mq_lock)) {
		mq_clear_sbinfo(ns);
		spin_unlock(&mq_lock);

		if (llist_add(&ns->mnt_llist, &free_ipc_list))
			schedule_work(&free_ipc_work);
	}
}

static inline struct ipc_namespace *to_ipc_ns(struct ns_common *ns)
{
	return container_of(ns, struct ipc_namespace, ns);
}

static struct ns_common *ipcns_get(struct task_struct *task)
{
	struct ipc_namespace *ns = NULL;
	struct nsproxy *nsproxy;

	task_lock(task);
	nsproxy = task->nsproxy;
	if (nsproxy)
		ns = get_ipc_ns(nsproxy->ipc_ns);
	task_unlock(task);

/* 학습 해설
 * IPC namespace 설치: 입력 참조 계약과 UTS의 순서 차이
 * 서로 비슷한 namespace 구현이라도 참조를 얻고 놓는 줄의 순서가 같다고 가정하면 안 됩니다. 설치할 새 namespace는 호출자가 유효한 수명으로 넘겨야 하며,설치 함수 내부의 교체 순서와 외부에서 이미 보유한 참조를 함께 보아야 합니다.
 * ipcns_install은 대상 user_ns와 nsset->cred->user_ns에서 CAP_SYS_ADMIN을 각각 검사합니다. 실패는 변경 전 -EPERM입니다. 성공하면 기존 nsproxy->ipc_ns를 put한 다음 새 ns를 get하여 대입합니다. ipcns_get은 task_lock 안에서 nsproxy를 읽고 get_ipc_ns로 참조를 얻으며,ipcns_put은 공통 ns 포인터를 container_of로 되돌려 put합니다.
 * 같은 객체를 다시 설치하되 기존 연결 참조1과 호출자가 유지하는 대상 참조1로 합계2인 경우,기존 put으로1,새 get으로2가 됩니다. 입력에 살아 있는 별도 참조가 있다는 계약을 빼고 단순 참조1 예제를 적용하면 잘못된 사용을 정상 동작처럼 설명하게 됩니다. UTS install의 get-then-put 순서를 IPC에도 그대로 복사해 설명해서는 안 됩니다.
 */
static int ipcns_install(struct nsset *nsset, struct ns_common *new)
{
	struct nsproxy *nsproxy = nsset->nsproxy;
	struct ipc_namespace *ns = to_ipc_ns(new);
	if (!ns_capable(ns->user_ns, CAP_SYS_ADMIN) ||
	    !ns_capable(nsset->cred->user_ns, CAP_SYS_ADMIN))
		return -EPERM;

	put_ipc_ns(nsproxy->ipc_ns);
	nsproxy->ipc_ns = get_ipc_ns(ns);
	return 0;
}

static struct user_namespace *ipcns_owner(struct ns_common *ns)
{
	return to_ipc_ns(ns)->user_ns;
}

const struct proc_ns_operations ipcns_operations = {
	.name		= "ipc",
	.type		= CLONE_NEWIPC,
	.get		= ipcns_get,
	.put		= ipcns_put,
	.install	= ipcns_install,
	.owner		= ipcns_owner,
};

/* 학습 해설
 * Clock event 상태 전환: 콜백 성공 뒤에만 상태 기록
 * 하드웨어를 주기 모드나 단발 모드로 바꾸는 작업이 실패했는데 소프트웨어 상태만 먼저 바꾸면 다음 호출이 장치를 잘못 이해합니다. 장치 콜백의 결과를 확인한 뒤 상태를 갱신해야 하며,지원하지 않는 모드와 콜백이 없는 경우도 분리해 읽어야 합니다.
 * 외부 switch_state는 현재 상태와 같으면 아무 일도 하지 않습니다. 다르면 내부 helper를 호출해0일 때만 상태를 기록합니다. DUMMY 장치는 내부에서 즉시0입니다. DETACHED와 SHUTDOWN은 shutdown 콜백,PERIODIC과 ONESHOT은 해당 기능 비트를 확인한 뒤 콜백을 사용합니다. 기능 부족은 -ENOSYS입니다. ONESHOT_STOPPED는 기존 ONESHOT인지 확인하고 stopped 콜백이 없으면 -ENOSYS입니다.
 * PERIODIC 기능은 있지만 periodic 콜백이 없는 경우 내부 helper는0을 반환해 상태를 바꿉니다. 반면 ONESHOT_STOPPED는 콜백이 없으면 실패하므로 같은 규칙이 아닙니다. 콜백이 -5를 반환하면 외부 void 함수는 오류 숫자를 호출자에게 전달하지 않고 상태도 갱신하지 않습니다. 문서상 호출 시 인터럽트가 꺼져 있어야 합니다.
 */
void clockevents_switch_state(struct clock_event_device *dev,
			      enum clock_event_state state)
{
	if (clockevent_get_state(dev) != state) {
		if (__clockevents_switch_state(dev, state))
			return;

		clockevent_set_state(dev, state);

		/*
		 * A nsec2cyc multiplicator of 0 is invalid and we'd crash
		 * on it, so fix it up and emit a warning:
		 */
		if (clockevent_state_oneshot(dev)) {
			if (WARN_ON(!dev->mult))
				dev->mult = 1;
		}
	}
}

/**
 * clockevents_shutdown - shutdown the device and clear next_event
 * @dev:	device to shutdown
 */
void clockevents_shutdown(struct clock_event_device *dev)
{

/* 학습 해설
 * 타이머 최소 지연 재시도: 가까운 마감이 계속 실패할 때
 * 매우 가까운 시각을 타이머에 설정하는 동안 그 시각이 이미 지나면 장치가 요청을 거절할 수 있습니다. 같은 짧은 지연을 끝없이 재시도하면 CPU만 소비합니다. 이 코드는 빌드 설정에 따라 최소 지연을 늘리거나 제한된 횟수의 더 긴 상대 지연으로 재시도합니다.
 * MIN_ADJUST가 있으면 같은 min_delta_ns로 최대3회 실패 후 최소 지연을 늘립니다.5000ns 미만은5000으로,그 이상은 기존값의 절반을 더하며 한 jiffy인 NSEC_PER_SEC/HZ로 제한합니다. 이미 한도 이상에서 증가 요청이 오면 next_event를 KTIME_MAX로 하고 -ETIME입니다. MIN_ADJUST가 없으면 저장된 min_delta를 바꾸지 않고 지역 delta에 최소값을 누적하며10번 시도합니다.
 * 조정 모드에서 최소4000ns가 세 번 실패하면5000ns,다시 세 번 실패하면7500ns로 바뀝니다. 비조정 모드의 최소4000ns는4000,8000,...,40000ns를 최대10번 시도합니다. 각 시도는 새 ktime_get()에 그때의 delta를 더하므로 처음 시각에 고정된 누적 마감표가 아닙니다. dev->retries는 실제 set_next_event 시도 전에 증가합니다.
 */
static int clockevents_increase_min_delta(struct clock_event_device *dev)
{
	/* Nothing to do if we already reached the limit */
	if (dev->min_delta_ns >= MIN_DELTA_LIMIT) {
		printk_deferred(KERN_WARNING
				"CE: Reprogramming failure. Giving up\n");
		dev->next_event = KTIME_MAX;
		return -ETIME;
	}

	if (dev->min_delta_ns < 5000)
		dev->min_delta_ns = 5000;
	else
		dev->min_delta_ns += dev->min_delta_ns >> 1;

	if (dev->min_delta_ns > MIN_DELTA_LIMIT)
		dev->min_delta_ns = MIN_DELTA_LIMIT;

	printk_deferred(KERN_WARNING
			"CE: %s increased min_delta_ns to %llu nsec\n",
			dev->name ? dev->name : "?",
			(unsigned long long) dev->min_delta_ns);
	return 0;
}

/**
 * clockevents_program_min_delta - Set clock event device to the minimum delay.
 * @dev:	device to program
 *
 * Returns 0 on success, -ETIME when the retry loop failed.
 */

/* 학습 해설
 * 절대 마감 프로그래밍: Force와 KTIME 경로의 차이
 * 상위 타이머는 단조 시계 기준의 절대 마감을 다루지만 장치는 현재부터 남은 tick 수를 요구할 수 있습니다. 마감이 이미 지났거나 너무 멀고 가까운 경우를 조정해야 합니다. 또한 절대 ktime을 직접 받는 장치는 변환 경로를 건너뛰므로 force가 모든 장치에 같은 방식으로 적용되지는 않습니다.
 * expires가 음수이면 경고 후 -ETIME이며 next_event를 갱신하지 않습니다. 나머지는 next_event=expires로 저장하고 SHUTDOWN이면0입니다. ONESHOT이 아니면 경고하지만 계속합니다. KTIME 기능이 있으면 set_next_ktime 결과를 바로 반환합니다. 일반 경로는 expires-now를 계산해0 이하이면 force일 때 최소 지연을 시도하고,양수이면 최대·최소 범위로 제한해 tick으로 변환하고 set_next_event를 호출합니다. 그 실패도 force이면 최소 지연으로 재시도합니다.
 * 현재100000ns,마감99000ns인 일반 경로는 delta-1000이므로 force=false면 -ETIME,force=true면 최소 지연 경로입니다. 양수 delta10000,max8000,min2000이면 실제 변환 지연은8000ns지만 저장된 next_event는 원래 expires입니다. 최소 지연 helper에 들어가야 그 helper가 별도 next_event를 다시 기록합니다.
 */
int clockevents_program_event(struct clock_event_device *dev, ktime_t expires,
			      bool force)
{
	unsigned long long clc;
	int64_t delta;
	int rc;

	if (WARN_ON_ONCE(expires < 0))
		return -ETIME;

	dev->next_event = expires;

	if (clockevent_state_shutdown(dev))
		return 0;

	/* We must be in ONESHOT state here */
	WARN_ONCE(!clockevent_state_oneshot(dev), "Current state: %d\n",
		  clockevent_get_state(dev));

	/* Shortcut for clockevent devices that can deal with ktime. */
	if (dev->features & CLOCK_EVT_FEAT_KTIME)
		return dev->set_next_ktime(expires, dev);

	delta = ktime_to_ns(ktime_sub(expires, ktime_get()));
	if (delta <= 0)
		return force ? clockevents_program_min_delta(dev) : -ETIME;

/* 학습 해설
 * 타이머 장치 후보 선택: CPU 적합성과 모듈 참조를 함께 보기
 * 사용 중인 타이머 장치를 떼려면 그 CPU에 다음 인터럽트를 전달할 대체 장치가 필요합니다. 점수가 높아도 해당 CPU에 전달할 수 없거나 모듈이 해제 중이면 사용할 수 없습니다. 후보 선택과 코드 수명 확보를 함께 해야 장치 교체 뒤 사라진 콜백을 호출하지 않습니다.
 * clockevents_replace는 등록 목록에서 기존 장치와 DETACHED가 아닌 장치를 건너뜁니다. tick_check_replacement가 더 적합하다고 판단하고 try_module_get이 성공한 후보만 선택합니다. 새 후보를 택하면 앞서 선택한 후보의 모듈 참조를 put합니다. 최종 후보가 있으면 tick_install_replacement를 호출하고 기존 장치를 list_del_init합니다. 없으면 -EBUSY입니다.
 * 후보 A의 참조를 얻은 뒤 더 좋은 B를 찾았어도 B의 try_module_get이 실패하면 A를 유지합니다. B의 참조 획득이 성공한 다음에야 A를 놓습니다. tick helper는 CPU mask·IRQ affinity 가능성·CPU 전용 여부·ONESHOT 기능·rating을 함께 판단하므로 가장 큰 rating 숫자만 찾는 정렬 알고리즘이 아닙니다.
 */
static int clockevents_replace(struct clock_event_device *ced)
{
	struct clock_event_device *dev, *newdev = NULL;

	list_for_each_entry(dev, &clockevent_devices, list) {
		if (dev == ced || !clockevent_state_detached(dev))
			continue;

		if (!tick_check_replacement(newdev, dev))
			continue;

		if (!try_module_get(dev->owner))
			continue;

		if (newdev)
			module_put(newdev->owner);
		newdev = dev;
	}
	if (newdev) {
		tick_install_replacement(newdev);
		list_del_init(&ced->list);
	}
	return newdev ? 0 : -EBUSY;
}

/*
 * Called with clockevents_mutex and clockevents_lock held
 */

/* 학습 해설
 * 타이머 Unbind: 대상 CPU에서 대체 장치를 설치하기
 * CPU별 타이머 장치는 그 CPU의 tick 상태와 연결됩니다. 다른 CPU에서 목록만 지우면 실제 사용 중인 타이머 연결이 남을 수 있습니다. 먼저 사용 상태를 판별하고 필요할 때 대상 CPU에 동기 호출해 대체 장치를 설치합니다.
 * __clockevents_try_unbind는 DETACHED이면 목록에서 제거하고0입니다. 그 외에는 지정 CPU의 현재 tick 장치와 같으면 -EAGAIN,다르면 -EBUSY입니다. 대상 CPU의 __clockevents_unbind는 raw lock 안에서 이 검사를 하고 EAGAIN이면 replace를 시도합니다. clockevents_unbind는 결과를 -ENODEV로 초기화하고 smp_call_function_single의 wait 인자를1로 호출한 뒤 결과 필드를 반환합니다. 외부 unbind_device는 mutex로 감쌉니다.
 * DETACHED 장치는 대체 설치 없이 제거할 수 있습니다. 사용 중인 해당 CPU의 장치는 EAGAIN을 작업 재시도 신호로 사용하지만 곧바로 성공이라는 뜻은 아닙니다. replace가 후보를 찾지 못하면 최종 EBUSY가 됩니다. SMP 호출 자체가 콜백을 실행하지 못한 경우 결과 필드가 초기 ENODEV로 남을 수 있으며 이 함수는 SMP 호출의 반환값을 직접 전달하지 않습니다.
 */
static int __clockevents_try_unbind(struct clock_event_device *ced, int cpu)
{
	/* Fast track. Device is unused */
	if (clockevent_state_detached(ced)) {
		list_del_init(&ced->list);
		return 0;
	}

	return ced == per_cpu(tick_cpu_device, cpu).evtdev ? -EAGAIN : -EBUSY;
}

/*
 * SMP function call to unbind a device
 */
static void __clockevents_unbind(void *arg)
{
	struct ce_unbind *cu = arg;
	int res;

	raw_spin_lock(&clockevents_lock);
	res = __clockevents_try_unbind(cu->ce, smp_processor_id());
	if (res == -EAGAIN)
		res = clockevents_replace(cu->ce);
	cu->res = res;
	raw_spin_unlock(&clockevents_lock);
}

/* 학습 해설
 * 타이머 등록과 교환: 대기 목록으로 되돌려 다시 평가하기
 * 새 장치가 더 적합해 기존 장치를 교체하더라도 기존 장치가 다른 역할에 유용할 수 있습니다. 등록 목록과 임시 반환 목록을 나누면 교체 중 다시 선택하는 복잡한 흐름을 뒤로 미뤄 정리할 수 있습니다. CPU mask가 없는 장치의 기본값도 명시해야 합니다.
 * register는 상태를 DETACHED로 초기화합니다. cpumask가 없으면 여러 possible CPU에 대해 경고하고 현재 CPU 하나의 mask를 지정합니다. 포인터가 cpu_all_mask와 같으면 경고 후 cpu_possible_mask로 바꿉니다. raw lock과 IRQ 상태 보호 안에서 등록 목록에 넣고 tick_check_new_device 후 notify_released를 호출합니다. notify는 반환 목록의 앞 장치를 등록 목록으로 옮겨 다시 평가합니다.
 * exchange는 old가 있으면 모듈 참조를 놓고 DETACHED 전환을 요청한 뒤 released 목록으로 옮깁니다. new가 있으면 DETACHED가 아니면 BUG_ON이며 shutdown합니다. old=NULL 또는 new=NULL도 각각 허용됩니다. 등록 목록 A,B,C에서 B를 반환 목록으로 옮겨도 B 객체를 새로 복사하거나 해제하지 않고 같은 list 노드의 소속만 바꿉니다.
 */
void clockevents_register_device(struct clock_event_device *dev)
{
	unsigned long flags;

	/* Initialize state to DETACHED */
	clockevent_set_state(dev, CLOCK_EVT_STATE_DETACHED);

	if (!dev->cpumask) {
		WARN_ON(num_possible_cpus() > 1);
		dev->cpumask = cpumask_of(smp_processor_id());
	}

	if (dev->cpumask == cpu_all_mask) {
		WARN(1, "%s cpumask == cpu_all_mask, using cpu_possible_mask instead\n",
		     dev->name);
		dev->cpumask = cpu_possible_mask;
	}

	raw_spin_lock_irqsave(&clockevents_lock, flags);

	list_add(&dev->list, &clockevent_devices);
	tick_check_new_device(dev);
	clockevents_notify_released();

	raw_spin_unlock_irqrestore(&clockevents_lock, flags);
}

/* 학습 해설
 * 타이머 주파수 변경: 같은 나노초 마감을 새 Tick 배율로 설정
 * 하드웨어 주파수가 바뀌면 같은 tick 수가 나타내는 시간이 달라집니다. 절대 마감을 유지하려면 변환 배율을 다시 계산하고 장치에 새 tick 값을 써야 합니다. 최대 표현 기간까지 무제한 정밀도를 유지할 수 없으므로 배율 계산용 기간도 제한합니다.
 * config는 ONESHOT 기능이 없으면 반환합니다. max_delta_ticks/freq의 정수 초를 구해0이면1로 하고,600초보다 크면서 tick 상한도 UINT_MAX보다 크면600으로 제한합니다. mult/shift를 계산하고 최소·최대 tick을 각각 cev_delta2ns의 다른 경계 정책으로 바꿉니다. config_and_register는 tick 한도 필드를 먼저 저장한 뒤 config와 register를 호출합니다.
 * 최대 tick2^40,주파수1000000이면 정수 초1099511이지만 배율 계산용 sec는600입니다. 이것은 max_delta_ticks 자체를600초 분량으로 덮어쓰는 줄이 아닙니다. __update_freq는 배율을 갱신한 뒤 ONESHOT이면 기존 next_event를 force=false로 재설정하고,PERIODIC이면 내부 상태 콜백을 직접 호출합니다. 같은 PERIODIC 상태여도 하드웨어를 재설정해야 하므로 외부의 같은 상태 생략 wrapper를 사용하지 않습니다.
 */
static void clockevents_config(struct clock_event_device *dev, u32 freq)
{
	u64 sec;

	if (!(dev->features & CLOCK_EVT_FEAT_ONESHOT))
		return;

	/*
	 * Calculate the maximum number of seconds we can sleep. Limit
	 * to 10 minutes for hardware which can program more than
	 * 32bit ticks so we still get reasonable conversion values.
	 */
	sec = dev->max_delta_ticks;
	do_div(sec, freq);
	if (!sec)
		sec = 1;
	else if (sec > 600 && dev->max_delta_ticks > UINT_MAX)
		sec = 600;

	clockevents_calc_mult_shift(dev, freq, sec);
	dev->min_delta_ns = cev_delta2ns(dev->min_delta_ticks, dev, false);
	dev->max_delta_ns = cev_delta2ns(dev->max_delta_ticks, dev, true);
}

