 * clockevents_config_and_register - Configure and register a clock event device
 * @dev:	device to register
 * @freq:	The clock frequency
 * @min_delta:	The minimum clock ticks to program in oneshot mode
 * @max_delta:	The maximum clock ticks to program in oneshot mode
 *
 * min/max_delta can be 0 for devices which do not support oneshot mode.
 */

/* 학습 해설
 * 타이머 Suspend와 CPU 제거: 역순 복귀 짝과 단일 CPU 장치 정리
 * 시스템 절전이나 CPU 제거에서는 타이머 장치가 더 이상 실행 이벤트를 전달하지 않도록 단계별로 정리해야 합니다. 여러 CPU가 함께 쓰는 장치까지 단일 CPU와 함께 제거하면 다른 CPU의 시간 처리가 끊깁니다. 목록 순서와 장치 사용 범위를 구별합니다.
 * suspend는 등록 목록을 역순,resume은 정순으로 순회하며 콜백이 있고 DETACHED가 아닌 장치에만 호출합니다. HOTPLUG의 tick_cleanup_dead_cpu는 IRQ와 raw lock 보호 아래 tick_shutdown 후 released 목록을 모두 떼어냅니다. 등록 목록에서는 사라진 CPU가 mask에 있고 mask 무게가1이며 broadcast 장치가 아닐 때만 제거하며 DETACHED가 아니면 BUG_ON입니다.
 * 현재 목록 순서가 A,B,C이면 모두 대상일 때 suspend C,B,A,resume A,B,C입니다. 이것을 실제 등록 시간 순서라고 단정하면 list_add나 list_move의 영향을 놓칩니다. CPU2 전용 mask{2}는 제거 후보이고 mask{2,3}은 무게2라 이 조건으로 제거하지 않습니다. broadcast 장치도 제외합니다.
 */
void clockevents_suspend(void)
{
	struct clock_event_device *dev;

	list_for_each_entry_reverse(dev, &clockevent_devices, list)
		if (dev->suspend && !clockevent_state_detached(dev))
			dev->suspend(dev);
}

/**
 * clockevents_resume - resume clock devices
 */
void clockevents_resume(void)
{
	struct clock_event_device *dev;

	list_for_each_entry(dev, &clockevent_devices, list)
		if (dev->resume && !clockevent_state_detached(dev))
			dev->resume(dev);
}

