static struct kmem_cache *create_pid_cachep(unsigned int level)
{
	/* Level 0 is init_pid_ns.pid_cachep */
	struct kmem_cache **pkc = &pid_cache[level - 1];
	struct kmem_cache *kc;
	char name[4 + 10 + 1];
	unsigned int len;

	kc = READ_ONCE(*pkc);
	if (kc)
		return kc;

	snprintf(name, sizeof(name), "pid_%u", level + 1);
	len = struct_size_t(struct pid, numbers, level + 1);
	mutex_lock(&pid_caches_mutex);
	/* Name collision forces to do allocation under mutex. */
	if (!*pkc)
		*pkc = kmem_cache_create(name, len, 0,
					 SLAB_HWCACHE_ALIGN | SLAB_ACCOUNT, NULL);
	mutex_unlock(&pid_caches_mutex);
	/* current can fail, but someone else can succeed. */
	return READ_ONCE(*pkc);
}

static struct ucounts *inc_pid_namespaces(struct user_namespace *ns)
{

/* 학습 해설
 * PID namespace 생성: 계층 제한과 생성 회계의 단계별 정리
 * PID 공간을 중첩할 때 무제한 깊이를 허용하면 PID 객체의 조상 번호 배열과 계층 처리가 계속 커집니다. 또한 사용자별 생성 개수와 user namespace의 포함 관계도 지켜야 합니다. 이 제약은 메모리 할당 가능 여부와 서로 다른 검사입니다.
 * create는 parent level+1을 구하고 부모의 user namespace 안에 새 user namespace가 포함되는지 검사해 실패는 EINVAL입니다. 깊이32 초과 또는 UCOUNT_PID_NAMESPACES 획득 실패는 ENOSPC입니다.0 초기화한 namespace를 할당하고 IDR,깊이별 PID cache,namespace 번호를 준비합니다. 성공하면 참조1,부모·user_ns 참조,ucounts,PIDNS_ADDING을 설정합니다.
 * 부모 level32이면 새 level33이므로 객체를 할당하기 전에 ENOSPC입니다. cache 또는 namespace 번호 단계가 실패하면 IDR과 namespace 객체를 정리하고 생성 몫을 반납합니다. 성공한 깊이별 공유 cache는 실패한 namespace 하나 때문에 파괴하지 않습니다. CONFIG_SYSCTL과 MEMFD_CREATE가 있으면 부모 계층의 유효 memfd_noexec 정책도 상속합니다.
 */
static struct pid_namespace *create_pid_namespace(struct user_namespace *user_ns,
	struct pid_namespace *parent_pid_ns)
{
	struct pid_namespace *ns;
	unsigned int level = parent_pid_ns->level + 1;
	struct ucounts *ucounts;
	int err;

	err = -EINVAL;
	if (!in_userns(parent_pid_ns->user_ns, user_ns))
		goto out;

	err = -ENOSPC;
	if (level > MAX_PID_NS_LEVEL)
		goto out;
	ucounts = inc_pid_namespaces(user_ns);
	if (!ucounts)
		goto out;

	err = -ENOMEM;
	ns = kmem_cache_zalloc(pid_ns_cachep, GFP_KERNEL);
	if (ns == NULL)
		goto out_dec;

	idr_init(&ns->idr);

/* 학습 해설
 * PID namespace 참조 반납: 부모 연쇄와 지연 메모리 해제
 * 자식 namespace는 부모가 살아 있어야 조상 번호와 계층 관계를 사용할 수 있습니다. 자식이 마지막 참조를 잃으면 그 자식이 보유한 부모 참조도 반납해야 합니다. 동시에 RCU 독자가 남을 수 있어 구조체 메모리는 즉시 해제하지 않습니다.
 * put_pid_ns는 init_pid_ns가 아닌 동안 부모 포인터를 보관하고 참조를 감소시킵니다. 아직 참조가 남으면 반복을 끝냅니다.0이면 destroy_pid_namespace로 번호와 IDR을 정리하고 call_rcu를 예약한 뒤 부모로 이동해 같은 처리를 반복합니다. delayed_free_pidns는 유예 뒤 생성 회계,user_ns 참조,namespace slab 객체를 정리합니다.
 * 자식 C의 참조1,부모 P의 참조2이면 C를0으로 내려 지연 파괴를 예약한 뒤 P를1로 내려 멈춥니다. P도1이었다면 P까지0으로 내려 연쇄 정리할 수 있습니다. init_pid_ns에는 이 감소를 적용하지 않습니다. 자식의 RCU 콜백이 실행되기 전에도 부모 참조 반납 반복은 진행되므로 모든 단계가 콜백 안에서 실행된다고 설명하면 틀립니다.
 */
void put_pid_ns(struct pid_namespace *ns)
{
	struct pid_namespace *parent;

	while (ns != &init_pid_ns) {
		parent = ns->parent;
		if (!refcount_dec_and_test(&ns->ns.count))
			break;
		destroy_pid_namespace(ns);
		ns = parent;
	}
}
EXPORT_SYMBOL_GPL(put_pid_ns);

void zap_pid_ns_processes(struct pid_namespace *pid_ns)
{
	int nr;
	int rc;
	struct task_struct *task, *me = current;
	int init_pids = thread_group_leader(me) ? 1 : 2;
	struct pid *pid;

	/* Don't allow any more processes into the pid namespace */
	disable_pid_allocation(pid_ns);

	/*
	 * Ignore SIGCHLD causing any terminated children to autoreap.
	 * This speeds up the namespace shutdown, plus see the comment
	 * below.
	 */

/* 학습 해설
 * PID1 종료 준비: 새 할당 차단과 남은 태스크 종료 요청
 * namespace의 init 역할이 끝나는데 새 프로세스가 계속 들어오면 종료가 끝나지 않습니다. 먼저 신규 PID 할당을 막고 남은 태스크에 종료를 요청해야 합니다. 여러 스레드가 하나의 프로세스 그룹에 있어도 PID 테이블의 개별 태스크 번호와 그룹 단위를 혼동하면 안 됩니다.
 * zap은 disable_pid_allocation으로 ADDING 비트를 내립니다. 현재 태스크의 sighand 잠금 안에서 SIGCHLD 처리를 SIG_IGN으로 바꿔 종료한 자식의 자동 회수를 유도합니다. RCU와 tasklist 읽기 잠금 아래 IDR을 번호2부터 순회해 태스크가 있고 이미 fatal 신호가 대기 중이지 않으면 SIGKILL을 전달합니다.
 * IDR 번호1은 namespace init 역할이므로 순회를2에서 시작합니다. 번호2와3이 같은 스레드 그룹에 속해도 이 반복은 개별 PID 항목을 읽습니다. 원문은 중복 그룹 신호를 피하려고 전체 시스템 task list를 뒤지는 비용보다 이 방식을 택한 이유를 설명합니다. 신호 전달 요청은 태스크의 실제 종료·회수 완료와 같지 않습니다.
 */
void zap_pid_ns_processes(struct pid_namespace *pid_ns)
{
	int nr;
	int rc;
	struct task_struct *task, *me = current;
	int init_pids = thread_group_leader(me) ? 1 : 2;
	struct pid *pid;

	/* Don't allow any more processes into the pid namespace */
	disable_pid_allocation(pid_ns);

	/*
	 * Ignore SIGCHLD causing any terminated children to autoreap.
	 * This speeds up the namespace shutdown, plus see the comment
	 * below.
	 */
	spin_lock_irq(&me->sighand->siglock);
	me->sighand->action[SIGCHLD - 1].sa.sa_handler = SIG_IGN;
	spin_unlock_irq(&me->sighand->siglock);

	/*
	 * The last thread in the cgroup-init thread group is terminating.
	 * Find remaining pid_ts in the namespace, signal and wait for them
	 * to exit.
	 *
	 * Note:  This signals each threads in the namespace - even those that
	 * 	  belong to the same thread group, To avoid this, we would have
	 * 	  to walk the entire tasklist looking a processes in this
	 * 	  namespace, but that could be unnecessarily expensive if the
	 * 	  pid namespace has just a few processes. Or we need to
	 * 	  maintain a tasklist for each pid namespace.
	 *
	 */

/* 학습 해설
 * PID namespace 종료 대기: ECHILD 이후에도 기다리는 이유
 * 자식 wait에서 ECHILD를 받았다고 namespace 안의 모든 프로세스가 없어졌다는 뜻은 아닙니다. 부모가 바깥 namespace에 있는 zombie나 wait가 놓치는 EXIT_DEAD 상태가 남을 수 있습니다. child_reaper가 먼저 사라지면 나중에 재부모화되는 객체를 처리할 수 없습니다.
 * zap은 init_pids를 현재 태스크가 그룹 leader이면1,아니면2로 설정합니다. wait4 반복이 끝난 뒤 TASK_INTERRUPTIBLE을 먼저 설정하고 pid_allocated가 init_pids인지 검사합니다. 다르면 schedule하고 다시 검사합니다. 같으면 반복을 나와 TASK_RUNNING으로 복원합니다. free_pid는 개수가2 또는1로 줄 때 child_reaper를 깨웁니다.
 * 잔여 pid_allocated4,init_pids1이면 wait4가 ECHILD여도 이 루프는 종료하지 않습니다. 다른 태스크의 PID가 차례로 반납돼1이 되어야 끝납니다. 상태를 먼저 잠듦 가능 상태로 설정한 뒤 조건을 검사하는 순서는 조건 갱신·깨움과의 경합에서 중요합니다. 이 값은 단순 현재 실행 중 태스크 수를 세는 사용자 목록과 같다고 가정하면 안 됩니다.
 */
void zap_pid_ns_processes(struct pid_namespace *pid_ns)
{
	int nr;
	int rc;
	struct task_struct *task, *me = current;
	int init_pids = thread_group_leader(me) ? 1 : 2;
	struct pid *pid;

	/* Don't allow any more processes into the pid namespace */
	disable_pid_allocation(pid_ns);

	/*
	 * Ignore SIGCHLD causing any terminated children to autoreap.
	 * This speeds up the namespace shutdown, plus see the comment
	 * below.
	 */
	spin_lock_irq(&me->sighand->siglock);
	me->sighand->action[SIGCHLD - 1].sa.sa_handler = SIG_IGN;
	spin_unlock_irq(&me->sighand->siglock);

	/*
	 * The last thread in the cgroup-init thread group is terminating.
	 * Find remaining pid_ts in the namespace, signal and wait for them
	 * to exit.
	 *
	 * Note:  This signals each threads in the namespace - even those that
	 * 	  belong to the same thread group, To avoid this, we would have
	 * 	  to walk the entire tasklist looking a processes in this
	 * 	  namespace, but that could be unnecessarily expensive if the
	 * 	  pid namespace has just a few processes. Or we need to
	 * 	  maintain a tasklist for each pid namespace.
	 *
	 */

/* 학습 해설
 * PID namespace 설치: 현재 PID와 앞으로 생길 자식의 공간
 * 실행 중인 프로세스의 PID가 갑자기 바깥 공간으로 옮겨지면 부모가 fork 결과로 받은 번호와 격리 관계가 깨질 수 있습니다. PID namespace 설치는 현재 active 공간을 곧바로 교체하는 대신 이후 자식이 사용할 공간을 지정하며,현재 공간의 자손으로 범위를 제한합니다.
 * install은 대상 user_ns와 nsset 자격의 user_ns에 대한 CAP_SYS_ADMIN을 검사합니다. 대상 level이 active보다 작으면 EINVAL입니다. 대상에서 부모를 따라 active level까지 올라가 정확히 같은 active 객체인지 확인합니다. 성공하면 기존 pid_ns_for_children 참조를 놓고 새 참조를 얻어 대입합니다. 동일 깊이의 다른 형제 namespace도 거절됩니다.
 * active A가 level2,대상 D가 level4이면 D→부모→level2의 객체가 A인지 확인합니다. 숫자 깊이가 같다고 같은 계층은 아닙니다. pidns_get은 RCU 아래 태스크의 active 공간을 조회하지만 pidns_for_children_get은 task_lock 아래 nsproxy의 미래 자식 공간을 얻고,tasklist 잠금 아래 child_reaper가 아직 없으면 참조를 반납해 NULL을 반환합니다.
 */
static int pidns_install(struct nsset *nsset, struct ns_common *ns)
{
	struct nsproxy *nsproxy = nsset->nsproxy;
	struct pid_namespace *active = task_active_pid_ns(current);
	struct pid_namespace *ancestor, *new = to_pid_ns(ns);

	if (!ns_capable(new->user_ns, CAP_SYS_ADMIN) ||
	    !ns_capable(nsset->cred->user_ns, CAP_SYS_ADMIN))
		return -EPERM;

	/*
	 * Only allow entering the current active pid namespace
	 * or a child of the current active pid namespace.
	 *
	 * This is required for fork to return a usable pid value and
	 * this maintains the property that processes and their
	 * children can not escape their current pid namespace.
	 */
	if (new->level < active->level)
		return -EINVAL;

	ancestor = new;
	while (ancestor->level > active->level)
		ancestor = ancestor->parent;
	if (ancestor != active)
		return -EINVAL;

/* 학습 해설
 * PID 부모 조회: 조상 밖으로 나가지 못하는 반환 규칙
 * 중첩된 namespace 구조를 조회하는 것 자체도 외부 공간의 정보를 노출할 수 있습니다. 요청 대상의 부모를 반환하더라도 그 부모가 현재 active namespace 안의 자손 범위에 있는지 검사해야 현재 격리 경계를 넘어가는 조회를 제한할 수 있습니다.
 * pidns_get_parent는 대상의 parent를 별도로 보관하고 그 지점부터 조상을 따라갑니다. NULL에 도달하면 EPERM 오류 포인터이고 active와 같은 객체를 만나면 통과합니다. 실제 반환은 탐색 끝의 active가 아니라 처음 보관한 대상의 직접 부모에 get_pid_ns한 ns_common 주소입니다.
 * active A 안에 B,그 안에 C가 있으면 C의 부모 조회는 B에서 시작해 A를 만나 허용하고 B를 반환합니다. A 자신의 부모를 요청하면 A 위쪽에서 탐색을 시작하므로 A를 다시 만날 수 없어 EPERM입니다. 검사 기준 객체와 반환 객체가 다르다는 점을 직접 계층 그림으로 확인하면 이해하기 쉽습니다.
 */
static struct ns_common *pidns_get_parent(struct ns_common *ns)
{
	struct pid_namespace *active = task_active_pid_ns(current);
	struct pid_namespace *pid_ns, *p;

	/* See if the parent is in the current namespace */
	pid_ns = p = to_pid_ns(ns)->parent;
	for (;;) {
		if (!p)
			return ERR_PTR(-EPERM);
		if (p == active)
			break;
		p = p->parent;
	}

	return &get_pid_ns(pid_ns)->ns;
}

static struct user_namespace *pidns_owner(struct ns_common *ns)
{
	return to_pid_ns(ns)->user_ns;
}

const struct proc_ns_operations pidns_operations = {
	.name		= "pid",
	.type		= CLONE_NEWPID,

/* 학습 해설
 * PID 재시작과 ns_last_pid: 전체 시스템과 namespace 범위 구분
 * 컨테이너 안의 재시작 요청을 물리 컴퓨터 재부팅과 동일하게 처리하면 다른 작업까지 영향을 받습니다. 이 helper는 초기 PID namespace와 중첩 공간을 구분해 중첩 공간의 init을 종료시키는 방식으로 요청을 전달합니다. 복원용 PID 배정 커서도 현재 namespace에 한정해 다룹니다.
 * reboot_pid_ns는 init_pid_ns이면0을 반환합니다. 중첩 공간의 RESTART와 RESTART2는 reboot=SIGHUP,POWER_OFF와 HALT는 SIGINT로 저장하며 나머지는 EINVAL입니다. tasklist 읽기 잠금 아래 child_reaper에 SIGKILL을 보내고 호출 태스크는 do_exit(0)합니다. 저장한 reboot 값은 앞의 zap 종료 경로에서 group_exit_code에 쓰입니다.
 * SIGHUP을 저장한다고 child_reaper에 실제로 보내는 신호도 SIGHUP이라고 읽으면 안 됩니다. 전달 신호는 SIGKILL이고 저장값은 이후 종료 결과에 사용됩니다. CHECKPOINT_RESTORE의 ns_last_pid handler는 IDR cursor-1을 임시 정수로 읽고,minmax 처리에 성공한 쓰기만 cursor=next+1로 설정합니다. 입력100이면 다음 후보 커서는101이지만 이미 사용 중인 번호까지 반드시101로 배정한다고 보장하지 않습니다.
 */
int reboot_pid_ns(struct pid_namespace *pid_ns, int cmd)
{
	if (pid_ns == &init_pid_ns)
		return 0;

	switch (cmd) {
	case LINUX_REBOOT_CMD_RESTART2:
	case LINUX_REBOOT_CMD_RESTART:
		pid_ns->reboot = SIGHUP;
		break;

	case LINUX_REBOOT_CMD_POWER_OFF:
	case LINUX_REBOOT_CMD_HALT:
		pid_ns->reboot = SIGINT;
		break;
	default:
		return -EINVAL;
	}

	read_lock(&tasklist_lock);
	send_sig(SIGKILL, pid_ns->child_reaper, 1);
	read_unlock(&tasklist_lock);

	do_exit(0);

	/* Not reached */

/* 학습 해설
 * PCM DMA 메모리 회계: 요청량 예약 뒤 실제 할당량 보정
 * 여러 오디오 스트림이 동시에 DMA 버퍼를 만들면 같은 사운드 카드의 메모리 한도를 경쟁해서 사용할 수 있습니다. 할당을 끝낸 뒤에만 합계를 더하면 두 요청이 모두 아직 비어 있다고 판단할 수 있습니다. 먼저 요청량을 예약하고 실제 할당 후 차이를 보정하는 방식이 필요합니다.
 * do_alloc_pages는 card의 memory_mutex 안에서 총량+요청량이 max_alloc_per_card를 넘는지 확인하고 요청량을 더합니다. 한도0은 이 검사를 끕니다. 잠금을 놓고 playback이면 DMA_TO_DEVICE,그 외에는 DMA_FROM_DEVICE로 할당합니다. 성공 시 dmab->bytes가 요청과 다르면 차이를 회계에 반영하고 실패하면 예약량을 뺍니다.
 * 현재10MiB,요청4MiB이면 잠금 안에서14MiB를 예약합니다. 실제 할당이5MiB이면 나중에15MiB로 보정하고 실패했으면10MiB로 되돌립니다. 기본 카드 한도는32MiB입니다. 요청 합계 검사 뒤 실제 할당량이 커지는 보정에는 같은 한도 재검사가 없으므로 최종 실제 합계가 절대 한도를 넘지 않는다고 주장하면 안 됩니다.
 */
static int do_alloc_pages(struct snd_card *card, int type, struct device *dev,
			  int str, size_t size, struct snd_dma_buffer *dmab)
{
	enum dma_data_direction dir;
	int err;

	/* check and reserve the requested size */
	scoped_guard(mutex, &card->memory_mutex) {
		if (max_alloc_per_card &&
		    card->total_pcm_alloc_bytes + size > max_alloc_per_card)
			return -ENOMEM;
		__update_allocated_size(card, size);
	}

	if (str == SNDRV_PCM_STREAM_PLAYBACK)
		dir = DMA_TO_DEVICE;
	else
		dir = DMA_FROM_DEVICE;
	err = snd_dma_alloc_dir_pages(type, dev, dir, size, dmab);
	if (!err) {
		/* the actual allocation size might be bigger than requested,
		 * and we need to correct the account
		 */
		if (dmab->bytes != size)
			update_allocated_size(card, dmab->bytes - size);
	} else {
